-- One row per user whose data changed. The app subscribes to its own row
-- (Supabase Realtime) and refreshes when it changes. Lives in public so Realtime
-- can check the row-level policy below.
create table if not exists public.pings (
  user_id uuid primary key,
  at      timestamptz not null default now()
);
alter table public.pings enable row level security;
drop policy if exists pings_own on public.pings;
create policy pings_own on public.pings for select using (user_id = auth.uid());

do $$ declare t text; begin
  for t in select tablename from pg_tables where schemaname = 'app' loop
    execute format('alter table app.%I enable row level security', t);
  end loop;
end $$;

-- >>> db/core/20_helpers.sql
-- Shared helpers for the API functions.

-- Tell a user's open app to refresh.
create or replace function app.ping(u uuid) returns void
language sql as $$
  insert into public.pings(user_id, at) values (u, clock_timestamp())
  on conflict (user_id) do update set at = excluded.at
$$;

create or replace function app.ping_admins() returns void
language sql as $$
  select app.ping(id) from app.profiles where role = 'admin' and not deleted
$$;

-- In-app notification. u = null sends it to the admin inbox.
create or replace function app.note(u uuid, msg text) returns void
language plpgsql as $$
begin
  insert into app.notifications(user_id, body, created_at) values (u, msg, app.now());
  if u is null then perform app.ping_admins(); else perform app.ping(u); end if;
end $$;

create or replace function app.pname(u uuid) returns text
language sql stable as $$ select coalesce((select name from app.profiles where id = u), 'A student') $$;

create or replace function app.first_name(u uuid) returns text
language sql stable as $$ select split_part(app.pname(u), ' ', 1) $$;

-- "Tolu A."
create or replace function app.short_name(u uuid) returns text
language sql stable as $$
  select case when position(' ' in n) > 0
              then split_part(n, ' ', 1) || ' ' || left(split_part(n, ' ', 2), 1) || '.'
              else n end
  from (select app.pname(u) as n) x
$$;

create or replace function app.role_of(u uuid) returns text
language sql stable as $$ select role from app.profiles where id = u and not deleted $$;

-- Guards. Each returns the caller's id or raises a readable error.
create or replace function app.need_login() returns uuid
language plpgsql stable as $$
declare u uuid := auth.uid();
begin
  if u is null or app.role_of(u) is null then perform app.fail('Log in first.'); end if;
  return u;
end $$;

create or replace function app.need_student(allow_suspended boolean default false) returns uuid
language plpgsql stable as $$
declare u uuid := app.need_login(); p app.profiles;
begin
  select * into p from app.profiles where id = u;
  if p.role <> 'student' then perform app.fail('Only students can do this.'); end if;
  if p.suspended and not allow_suspended then
    perform app.fail('Your account is suspended. Reason: ' || coalesce(p.suspend_reason, 'not given') || '. Contact support to appeal.');
  end if;
  return u;
end $$;

create or replace function app.need_agent(allow_unverified boolean default false) returns uuid
language plpgsql stable as $$
declare u uuid := app.need_login(); st text;
begin
  if app.role_of(u) <> 'agent' then perform app.fail('Only agents can do this.'); end if;
  select status into st from app.agents where id = u;
  if st = 'suspended' then perform app.fail('Your account is suspended. Contact support to appeal.'); end if;
  if not allow_unverified and st <> 'verified' then perform app.fail('Your account is waiting for verification.'); end if;
  return u;
end $$;

create or replace function app.need_admin() returns uuid
language plpgsql stable as $$
declare u uuid := app.need_login();
begin
  if app.role_of(u) <> 'admin' then perform app.fail('Only admins can do this.'); end if;
  return u;
end $$;

create or replace function app.need_demo() returns void
language plpgsql stable as $$
begin
  if not (app.cfg()).demo then perform app.fail('This is only available in demo mode.'); end if;
end $$;

-- Agent trust score (same formula as the demo).
create or replace function app.update_trust(a uuid) returns void
language sql as $$
  update app.agents set trust = case
    when ratings = 0 and insp_done = 0 then 0
    else greatest(0, least(100, round(40 + rating * 8 + least(insp_done, 50) * 0.2
           - disputes * 5 - cancels * 3 - mismatches * 4 - no_shows * 8)))::int end
  where id = a
$$;

create or replace function app.house_live(h app.houses) returns boolean
language sql stable as $$
  select h.mod = 'live' and not h.deleted and not h.paused
     and exists (select 1 from app.agents a where a.id = h.agent_id and a.status = 'verified')
$$;

create or replace function app.active_count(r uuid) returns int
language sql stable as $$ select count(*)::int from app.keys where room_id = r and status = 'active' $$;

-- paused | taken | reserved | pending | open
create or replace function app.room_state(r app.rooms) returns text
language sql stable as $$
  select case
    when r.paused then 'paused'
    when app.active_count(r.id) >= r.cap then 'taken'
    when r.hold_ballot is not null then 'reserved'
    when r.pay_hold_until is not null and r.pay_hold_until > app.now() then 'pending'
    else 'open' end
$$;

create or replace function app.savings_balance(s uuid) returns int
language sql stable as $$
  select coalesce(sum(case when type = 'deposit' then amt else -amt end), 0)::int
  from app.savings_txns where student_id = s
$$;

create or replace function app.insp_done(s uuid, h uuid) returns boolean
language sql stable as $$
  select exists (select 1 from app.inspections where student_id = s and house_id = h and status = 'completed')
$$;

-- When a key's room becomes free for the next tenant: the key's end, or now if later.
create or replace function app.ballot_start(b app.ballots) returns timestamptz
language sql stable as $$
  select greatest(app.now(), coalesce((select end_at from app.keys where id = b.key_id and status = 'active'), app.now()))
$$;

-- Agent's share after commission.
create or replace function app.net(amount numeric) returns numeric
language sql stable as $$ select amount * (1 - (app.cfg()).commission) $$;

-- >>> db/core/30_state.sql
-- get_state(): everything the signed-in person is allowed to see, in the shape
-- the UI works with (times in epoch milliseconds, camelCase keys).
-- Anonymous visitors get public listings only.

create or replace function app.agent_json(a app.agents, p app.profiles, is_full boolean, with_phone boolean)
returns jsonb language sql stable as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', a.id, 'name', p.name, 'biz', a.biz, 'status', a.status,
    'since', to_char(coalesce(a.verified_at, a.created_at), 'Mon YYYY'),
    'resp', a.resp, 'rating', round(a.rating, 2), 'ratings', a.ratings, 'trust', a.trust,
    'inspDone', a.insp_done, 'disputes', a.disputes, 'cancels', a.cancels,
    'mismatches', a.mismatches, 'noShows', a.no_shows, 'bio', a.bio, 'photo', p.photo,
    'phone', case when with_phone or is_full then p.phone end,
    'email', case when is_full then p.email end,
    'payout', case when is_full then coalesce(a.payout_bank || ' •••• ' || right(a.payout_acct, 4), 'Not added') end,
    'payoutName', case when is_full then a.payout_name end,
    'docs', case when is_full then a.docs end,
    'docFiles', case when is_full then a.doc_files end,
    'btype', case when is_full then a.btype end,
    'rel', case when is_full then a.rel end,
    'rejectReason', case when is_full then a.reject_reason end,
    'suspendReason', case when is_full then a.suspend_reason end,
    'prefs', case when is_full then p.prefs end,
    'created', app.ms(a.created_at)
  ))
$$;

create or replace function public.get_state() returns jsonb
language plpgsql stable security definer set search_path = app, public as $$
declare
  u    uuid := auth.uid();
  me   app.profiles;
  v_role text;
  c    app.settings := app.cfg();
  t    timestamptz := app.now();
  res  jsonb;
begin
  if u is not null then
    select * into me from app.profiles where id = u and not deleted;
    v_role := me.role;
  end if;
  v_role := coalesce(v_role, 'anon');

  with
  hv as (  -- houses this person can see
    select h.* from app.houses h join app.agents a on a.id = h.agent_id
    where v_role = 'admin'
       or h.agent_id = u
       or (h.mod = 'live' and not h.deleted and a.status = 'verified')
       or (u is not null and (
            exists (select 1 from app.keys k where k.house_id = h.id and k.student_id = u)
         or exists (select 1 from app.inspections i where i.house_id = h.id and i.student_id = u)
         or exists (select 1 from app.payments p where p.house_id = h.id and p.student_id = u)
         or exists (select 1 from app.threads th where th.house_id = h.id and th.student_id = u)
         or exists (select 1 from app.favs f where f.house_id = h.id and f.student_id = u)
         or exists (select 1 from app.complaints cp where cp.house_id = h.id and (cp.author_id = u or cp.tenant_id = u))))
  ),
  kfull as (  -- keys shown in full (with the secret code)
    select k.* from app.keys k join app.houses h on h.id = k.house_id
    where v_role = 'admin' or k.student_id = u or h.agent_id = u
  ),
  kvis as (
    select k.*, true as is_full from kfull k
    union all
    select k.*, false as is_full from app.keys k
    where k.status = 'active' and k.house_id in (select id from hv)
      and k.id not in (select id from kfull)
  ),
  kcode as (
    select id, case when is_full then code else 'K-' || left(replace(id::text, '-', ''), 10) end as c from kvis
  ),
  rooms_j as (
    select r.house_id, jsonb_agg(jsonb_build_object(
      'id', r.id, 'name', r.name, 'price', r.price, 'cap', r.cap, 'capSaved', r.cap_saved,
      'paused', r.paused, 'furnished', r.furnished, 'hold', r.hold_ballot,
      'payHold', case when r.pay_hold_until > t then jsonb_build_object(
          'by', case when r.pay_hold_by = u or v_role = 'admin' then r.pay_hold_by::text else 'other' end,
          'until', app.ms(r.pay_hold_until)) end,
      'occ', coalesce((select jsonb_agg(kc.c order by k.start_at) from app.keys k join kcode kc on kc.id = k.id
                        where k.room_id = r.id and k.status = 'active'), '[]'::jsonb)
    ) order by r.sort, r.name) as rooms
    from app.rooms r where r.house_id in (select id from hv) and not r.archived
    group by r.house_id
  ),
  houses_j as (
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', h.id, 'agentId', h.agent_id, 'title', h.title, 'area', h.area, 'address', h.address,
      'km', h.km, 'type', h.type, 'shared', h.shared, 'art', h.art, 'times', to_jsonb(h.times),
      'days', to_jsonb(h.days), 'baths', h.baths, 'availFrom', h.avail_from, 'desc', h.descr,
      'amenities', to_jsonb(h.amenities), 'rules', to_jsonb(h.rules), 'photos', to_jsonb(h.photos),
      'mod', h.mod, 'paused', h.paused, 'deleted', h.deleted,
      'removedReason', h.removed_reason, 'removedNote', h.removed_note, 'removedAt', app.ms(h.removed_at),
      'created', app.ms(h.created_at)
    )) || jsonb_build_object('rooms', coalesce(rj.rooms, '[]'::jsonb)) order by h.created_at), '[]'::jsonb) as j
    from hv h left join rooms_j rj on rj.house_id = h.id
  ),
  keys_j as (
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', k.id, 'code', kc.c, 'payId', case when k.is_full then k.payment_id end,
      'houseId', k.house_id, 'roomId', k.room_id,
      'studentId', case when k.is_full then k.student_id end,
      'start', app.ms(k.start_at), 'end', app.ms(k.end_at), 'status', k.status,
      'movedIn', case when k.is_full then k.moved_in else false end,
      'autoRenew', case when k.is_full then k.auto_renew else false end,
      'shown', case when k.is_full then to_jsonb(k.shown) else '[]'::jsonb end,
      'notRenewing', case when k.is_full then k.not_renewing else false end,
      'renewals', case when k.is_full then k.renewals else 0 end,
      'hidden', case when k.is_full then null else true end
    )) order by k.start_at), '[]'::jsonb) as j
    from kvis k join kcode kc on kc.id = k.id
  ),
  pay_j as (
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', p.id, 'kind', p.kind, 'studentId', p.student_id, 'houseId', p.house_id, 'roomId', p.room_id,
      'amount', p.amount, 'savingsUsed', p.savings_used, 'method', p.method, 'ref', p.ref,
      'time', app.ms(coalesce(p.paid_at, p.created_at)), 'status', p.status,
      'releasedAt', app.ms(p.released_at), 'paidOutAt', app.ms(p.paid_out_at),
      'refundNeeded', case when (p.meta->>'refund_needed')::boolean then true end
    )) order by coalesce(p.paid_at, p.created_at)), '[]'::jsonb) as j
    from app.payments p left join app.houses h on h.id = p.house_id
    where p.kind <> 'deposit' and p.status not in ('pending', 'expired')
      and (v_role = 'admin' or p.student_id = u or (h.agent_id = u and p.status <> 'failed'))
  ),
  ins_j as (
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', i.id, 'houseId', i.house_id, 'studentId', i.student_id, 'slot', app.ms(i.slot), 'fee', i.fee,
      'payId', i.payment_id, 'status', i.status,
      'code', case when v_role in ('admin', 'agent') or c.demo then i.code end,
      'rating', i.rating, 'mismatch', i.mismatch, 'moves', i.moves, 'r24', i.r24, 'r1', i.r1,
      'refunded', i.refunded, 'byAdmin', i.by_admin, 'doneAt', app.ms(i.done_at)
    )) order by i.slot), '[]'::jsonb) as j
    from app.inspections i join app.houses h on h.id = i.house_id
    where v_role = 'admin' or i.student_id = u or h.agent_id = u
  ),
  bal as (
    select b.*, h.agent_id,
      array(select e.student_id from app.ballot_entries e where e.ballot_id = b.id order by e.created_at) as ents
    from app.ballots b join app.houses h on h.id = b.house_id
    where v_role = 'admin' or h.agent_id = u
       or (b.status in ('open', 'drawn') and b.house_id in (select id from hv))
       or exists (select 1 from app.ballot_entries e where e.ballot_id = b.id and e.student_id = u)
  ),
  bal_j as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', b.id, 'houseId', b.house_id, 'roomId', b.room_id,
      'keyCode', (select kc.c from kcode kc where kc.id = b.key_id),
      'created', app.ms(b.created_at), 'drawAt', app.ms(b.draw_at), 'status', b.status,
      'entrants', (select coalesce(jsonb_agg(case when v_role = 'admin' or b.agent_id = u or x = u then x::text else 'x' || n end), '[]'::jsonb)
                   from unnest(b.ents) with ordinality as e(x, n)),
      'order', (select coalesce(jsonb_agg(case when v_role = 'admin' or b.agent_id = u or x = u then x::text else 'x' || n end), '[]'::jsonb)
                from unnest(b.draw_order) with ordinality as e(x, n)),
      'offerIdx', b.offer_idx, 'offerAt', coalesce(app.ms(b.offer_at), 0),
      'winnerKey', (select kc.c from kcode kc where kc.id = b.winner_key)
    ) order by b.created_at), '[]'::jsonb) as j
    from bal b
  ),
  thr as (
    select th.* from app.threads th
    where v_role = 'admin' or th.student_id = u or th.agent_id = u
  ),
  thr_j as (
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', th.id, 'houseId', th.house_id, 'studentId', th.student_id, 'agentId', th.agent_id,
      'reported', th.reported, 'reportReason', th.report_reason, 'reportedBy', th.reported_by,
      'reportedAt', app.ms(th.reported_at), 'reportStatus', th.report_status,
      'blocked', th.blocked, 'blockedBy', th.blocked_by
    )) || jsonb_build_object('msgs', coalesce((
      select jsonb_agg(jsonb_build_object('from', m.sender, 'text', m.body, 't', app.ms(m.created_at),
                                          'read', m.read, 'flag', m.flag) order by m.created_at, m.id)
      from app.messages m where m.thread_id = th.id), '[]'::jsonb)) order by th.created_at), '[]'::jsonb) as j
    from thr th
  ),
  comp_j as (
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', cp.id, 'kind', cp.kind, 'authorId', cp.author_id, 'authorName', cp.author_name,
      'authorRole', cp.author_role, 'about', cp.about, 'houseId', cp.house_id, 'agentId', cp.agent_id,
      'tenantId', cp.tenant_id, 'tenantName', cp.tenant_name, 'reason', cp.reason, 'payId', cp.payment_id,
      'text', cp.body, 'status', cp.status, 'reply', cp.reply, 'replyBy', cp.reply_by,
      'removed', cp.removed, 't', app.ms(cp.created_at)
    )) order by cp.created_at desc), '[]'::jsonb) as j
    from app.complaints cp
    where v_role = 'admin' or cp.author_id = u or cp.agent_id = u or cp.tenant_id = u
       or (cp.kind = 'public' and not cp.removed)
  ),
  notes_j as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', n.id, 'to', coalesce(n.user_id::text, 'admin'), 'text', n.body, 't', app.ms(n.created_at), 'read', n.read
    ) order by n.created_at desc, n.id desc), '[]'::jsonb) as j
    from (select * from app.notifications n
          where u is not null and (n.user_id = u or (v_role = 'admin' and n.user_id is null))
          order by n.created_at desc limit 200) n
  ),
  -- people named in what this person can see
  stu_ids as (
    select u as id where v_role = 'student'
    union select student_id from kvis where is_full
    union select student_id from app.inspections i join app.houses h on h.id = i.house_id where h.agent_id = u
    union select student_id from thr
    union select x from bal b, unnest(b.ents || b.draw_order) x where b.agent_id = u
    union select student_id from app.payments p join app.houses h on h.id = p.house_id where h.agent_id = u
    union select p.id from app.profiles p where p.role = 'student' and v_role = 'admin'
  ),
  stu_j as (
    select coalesce(jsonb_object_agg(p.id, jsonb_strip_nulls(jsonb_build_object(
      'name', p.name, 'dept', p.dept, 'photo', p.photo, 'school', p.school,
      'suspended', p.suspended, 'suspendReason', case when p.id = u or v_role = 'admin' then p.suspend_reason end,
      'email', case when p.id = u or v_role = 'admin' then p.email end,
      'phone', case when p.id = u or v_role = 'admin' then p.phone end,
      'prefs', case when p.id = u then p.prefs end,
      'created', app.ms(p.created_at)
    ))), '{}'::jsonb) as j
    from app.profiles p where p.role = 'student' and p.id in (select id from stu_ids where id is not null)
  ),
  ag_j as (
    select coalesce(jsonb_object_agg(a.id, app.agent_json(a, p,
      v_role = 'admin' or a.id = u,
      exists (select 1 from app.inspections i join app.houses h on h.id = i.house_id
              where i.student_id = u and h.agent_id = a.id)
      or exists (select 1 from app.keys k join app.houses h on h.id = k.house_id
                 where k.student_id = u and h.agent_id = a.id))), '{}'::jsonb) as j
    from app.agents a join app.profiles p on p.id = a.id
    where v_role = 'admin' or a.id = u or a.status = 'verified'
       or a.id in (select agent_id from hv)
  ),
  sav_j as (
    select jsonb_build_object(
      'goal', coalesce((select jsonb_build_object('name', g.name, 'target', g.target, 'due', to_char(g.due, 'YYYY-MM-DD'),
                         'mode', g.mode, 'sched', g.sched, 'schedAmt', g.sched_amt, 'nextAuto', app.ms(g.next_auto))
                        from app.savings_goals g where g.student_id = u),
                       jsonb_build_object('name', 'Next session rent', 'target', 300000,
                         'due', to_char(t + interval '120 days', 'YYYY-MM-DD'), 'mode', 'flexible',
                         'sched', 'none', 'schedAmt', 0, 'nextAuto', null)),
      'txns', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'type', x.type, 'amt', x.amt,
                         't', app.ms(x.created_at), 'note', x.note) order by x.created_at desc)
                        from app.savings_txns x where x.student_id = u), '[]'::jsonb)) as j
  )
  select jsonb_build_object(
    'me', case when me.id is null then null else jsonb_strip_nulls(jsonb_build_object(
            'id', me.id, 'role', me.role, 'name', me.name, 'email', me.email, 'phone', me.phone,
            'photo', me.photo, 'dept', me.dept, 'suspended', me.suspended)) end,
    'cfg', jsonb_build_object('fee', c.insp_fee, 'comm', c.commission, 'term', c.term_days,
            'demo', c.demo, 'shift', c.shift_ms, 'paymentMode', c.payment_mode, 'holdMin', c.hold_minutes,
            'visitCutH', c.visit_cut_h, 'releaseDays', c.release_days, 'ballotDays', c.ballot_days,
            'offerHours', c.offer_hours),
    'now', app.ms(t),
    'houses', (select j from houses_j),
    'keys', (select j from keys_j),
    'payments', (select j from pay_j),
    'inspections', (select j from ins_j),
    'ballots', (select j from bal_j),
    'threads', (select j from thr_j),
    'complaints', (select j from comp_j),
    'notes', (select j from notes_j),
    'students', (select j from stu_j),
    'agents', (select j from ag_j),
    'favs', coalesce((select jsonb_agg(f.house_id order by f.created_at) from app.favs f where f.student_id = u), '[]'::jsonb),
    'savings', (select j from sav_j),
    'support', case when v_role = 'admin' then coalesce((select jsonb_agg(jsonb_build_object(
                  'id', s.id, 'name', s.name, 'contact', s.contact, 'who', s.who, 'topic', s.topic, 'msg', s.msg,
                  't', app.ms(s.created_at), 'status', s.status) order by s.created_at desc) from app.support s), '[]'::jsonb)
                else '[]'::jsonb end,
    'waitlist', case when v_role = 'admin' then coalesce((select jsonb_agg(jsonb_build_object(
                  'school', w.school, 'contact', w.contact, 'who', w.who, 't', app.ms(w.created_at)))
                  from app.waitlist w), '[]'::jsonb) else '[]'::jsonb end
  ) into res;
  return res;
end $$;

-- >>> db/core/40_checkout.sql
-- Checkout: room holds, starting a payment, and what happens once money arrives.
--
-- Flow: start_checkout() creates a pending payment and returns its reference.
--   * payment_mode = 'simulated' (demo / testing): the app calls simulate_pay(ref).
--   * payment_mode = 'paystack': the app opens Paystack checkout through the
--     paystack-init edge function; Paystack's webhook (or paystack-verify) calls
--     payment_confirmed(), which only the service role may run.
-- Either way app.finalize_payment() applies the effects exactly once.

-- Hold a room for a few minutes while the student pays, so nobody else can take it.
create or replace function public.hold_room(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(); r app.rooms; h app.houses; st text; c app.settings := app.cfg();
begin
  select * into r from app.rooms where id = (a->>'roomId')::uuid and not archived for update;
  if r.id is null then perform app.fail('This room is no longer listed.'); end if;
  select * into h from app.houses where id = r.house_id;
  if not app.house_live(h) then perform app.fail('This house is not taking bookings right now.'); end if;
  if not app.insp_done(u, h.id) then perform app.fail('Book and complete an inspection first. Rent unlocks after the visit.'); end if;
  st := app.room_state(r);
  if st = 'pending' and r.pay_hold_by = u then
    return jsonb_build_object('until', app.ms(r.pay_hold_until));
  end if;
  if st = 'pending' then perform app.fail('Another student is paying for this room right now. Try again in a few minutes.'); end if;
  if st <> 'open' then perform app.fail('Someone else just secured this room.'); end if;
  -- one hold per student
  update app.rooms set pay_hold_by = null, pay_hold_until = null where pay_hold_by = u and id <> r.id;
  update app.rooms set pay_hold_by = u, pay_hold_until = app.now() + make_interval(mins => c.hold_minutes)
   where id = r.id returning * into r;
  return jsonb_build_object('until', app.ms(r.pay_hold_until));
end $$;

create or replace function public.release_room(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true);
begin
  update app.rooms set pay_hold_by = null, pay_hold_until = null
   where id = (a->>'roomId')::uuid and pay_hold_by = u;
  return '{}'::jsonb;
end $$;

-- Start paying. a = {kind, houseId, roomId, slot, ballotId, keyCode, amount, useSav, method}
create or replace function public.start_checkout(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare
  kind text := a->>'kind';
  u uuid; c app.settings := app.cfg(); t timestamptz := app.now();
  h app.houses; r app.rooms; b app.ballots; k app.keys;
  amount int; sv int := 0; slot timestamptz; meta jsonb := '{}'::jsonb;
  pid uuid; ref text; method text := coalesce(nullif(a->>'method', ''), 'Card');
begin
  if kind not in ('inspection', 'rent', 'renewal', 'deposit') then perform app.fail('Unknown payment.'); end if;
  u := app.need_student();

  if kind = 'inspection' then
    select * into h from app.houses where id = (a->>'houseId')::uuid;
    if h.id is null or not app.house_live(h) then perform app.fail('This house is not taking visits right now.'); end if;
    if exists (select 1 from app.inspections where house_id = h.id and student_id = u and status = 'booked') then
      perform app.fail('You already have a visit booked at this house.');
    end if;
    slot := app.ts((a->>'slot')::bigint);
    if slot is null or slot <= t or slot > t + interval '15 days'
       or not (to_char(app.wat(slot), 'HH24:MI') = any (h.times))
       or not (extract(dow from app.wat(slot))::int = any (h.days)) then
      perform app.fail('That time is no longer available. Pick another slot.');
    end if;
    amount := c.insp_fee;
    meta := jsonb_build_object('slot', app.ms(slot));

  elsif kind = 'rent' then
    select * into r from app.rooms where id = (a->>'roomId')::uuid and not archived for update;
    if r.id is null then perform app.fail('This room is no longer listed.'); end if;
    select * into h from app.houses where id = r.house_id;
    if not app.insp_done(u, h.id) then perform app.fail('Book and complete an inspection first. Rent unlocks after the visit.'); end if;
    if nullif(a->>'ballotId', '') is not null then
      select * into b from app.ballots where id = (a->>'ballotId')::uuid and room_id = r.id;
      if b.id is null or b.status <> 'drawn' or b.draw_order[b.offer_idx + 1] is distinct from u then
        perform app.fail('This ballot offer is no longer yours. You have not been charged.');
      end if;
      meta := jsonb_build_object('ballot_id', b.id);
    else
      if not app.house_live(h) then perform app.fail('This house is not taking bookings right now.'); end if;
      if app.room_state(r) = 'open' then
        update app.rooms set pay_hold_by = null, pay_hold_until = null where pay_hold_by = u and id <> r.id;
        update app.rooms set pay_hold_by = u, pay_hold_until = t + make_interval(mins => c.hold_minutes) where id = r.id;
      elsif not (app.room_state(r) = 'pending' and r.pay_hold_by = u) then
        perform app.fail('Someone else just secured this room. You have not been charged.');
      end if;
    end if;
    amount := r.price;

  elsif kind = 'renewal' then
    select * into k from app.keys where code = a->>'keyCode' and student_id = u and status = 'active';
    if k.id is null then perform app.fail('This key is no longer active.'); end if;
    if exists (select 1 from app.ballots where key_id = k.id and status in ('drawn', 'filled')) then
      perform app.fail('Renewal closed when the ballot for this room was drawn.');
    end if;
    select * into r from app.rooms where id = k.room_id;
    select * into h from app.houses where id = k.house_id;
    amount := r.price;
    meta := jsonb_build_object('key_id', k.id);

  else -- deposit into rent savings
    amount := floor(coalesce((a->>'amount')::numeric, 0));
    if amount < 100 then perform app.fail('Enter at least ₦100.'); end if;
  end if;

  if kind in ('rent', 'renewal') and coalesce((a->>'useSav')::boolean, false) then
    sv := least(app.savings_balance(u), amount);
  end if;

  ref := app.gen_ref();
  insert into app.payments(kind, student_id, house_id, room_id, amount, savings_used, method, ref, status, provider, meta, created_at)
  values (kind, u, h.id, r.id, amount, sv, method, ref, 'pending',
          case when c.payment_mode = 'paystack' and amount > sv then 'paystack' else 'simulated' end, meta, t)
  returning id into pid;

  -- Fully covered by savings: nothing to charge.
  if amount - sv <= 0 then
    update app.payments set method = 'Rent savings' where id = pid;
    return jsonb_build_object('ref', ref, 'amount', amount, 'charge', 0, 'mode', 'none',
                              'result', app.finalize_payment(pid, null));
  end if;
  return jsonb_build_object('ref', ref, 'amount', amount, 'charge', amount - sv, 'mode', c.payment_mode);
end $$;

-- Apply a successful payment. Safe to call twice: the second call returns the first result.
create or replace function app.finalize_payment(pid uuid, provider_txn text) returns jsonb
language plpgsql as $$
declare
  p app.payments; c app.settings := app.cfg(); t timestamptz := app.now();
  h app.houses; r app.rooms; b app.ballots; k app.keys; ins_id uuid; th uuid; kid uuid;
  sname text; start_at timestamptz; res jsonb; ok boolean;
begin
  select * into p from app.payments where id = pid for update;
  if p.id is null then perform app.fail('Payment not found.'); end if;
  if p.status <> 'pending' then return coalesce(p.meta->'result', jsonb_build_object('ref', p.ref)); end if;
  select * into h from app.houses where id = p.house_id;
  sname := app.pname(p.student_id);

  if p.savings_used > 0 and app.savings_balance(p.student_id) < p.savings_used then
    res := jsonb_build_object('error', 'Your savings balance changed while you were paying. Any money taken will be refunded.');
    update app.payments set status = 'failed', provider_txn = finalize_payment.provider_txn,
      meta = meta || jsonb_build_object('result', res, 'refund_needed', p.amount > p.savings_used and p.provider <> 'simulated')
     where id = p.id;
    return res;
  end if;

  if p.kind = 'inspection' then
    update app.payments set status = 'paid', paid_at = t, provider_txn = finalize_payment.provider_txn where id = p.id;
    insert into app.inspections(house_id, student_id, slot, fee, payment_id, status, code, created_at)
    values (h.id, p.student_id, app.ts((p.meta->>'slot')::bigint), p.amount, p.id, 'booked', app.gen_digits(4), t)
    returning id into ins_id;
    perform app.note(p.student_id, format('Visit booked at %s for %s. Reminders go out 24 hours and 1 hour before.',
      h.title, app.fslot(app.ts((p.meta->>'slot')::bigint))));
    perform app.note(h.agent_id, format('%s booked a visit at %s for %s. %s of the fee is yours.',
      sname, h.title, app.fslot(app.ts((p.meta->>'slot')::bigint)), app.naira(app.net(p.amount))));
    insert into app.threads(house_id, student_id, agent_id, created_at) values (h.id, p.student_id, h.agent_id, t)
    on conflict (house_id, student_id) do nothing;
    select id into th from app.threads where house_id = h.id and student_id = p.student_id;
    insert into app.messages(thread_id, sender, body, created_at)
    values (th, 'a', format('Visit confirmed for %s at %s. Call me on %s when you get to the gate.',
      app.fslot(app.ts((p.meta->>'slot')::bigint)), h.address,
      coalesce((select phone from app.profiles where id = h.agent_id), 'the number on my profile')), t);
    res := jsonb_build_object('ref', p.ref, 'inspectionId', ins_id);

  elsif p.kind = 'rent' then
    select * into r from app.rooms where id = p.room_id for update;
    if p.meta ? 'ballot_id' then
      select * into b from app.ballots where id = (p.meta->>'ballot_id')::uuid for update;
      ok := b.status = 'drawn' and b.draw_order[b.offer_idx + 1] = p.student_id;
      if not ok then res := jsonb_build_object('error', 'This ballot offer is no longer yours. Any money taken will be refunded.'); end if;
    else
      ok := app.room_state(r) = 'open' or (app.room_state(r) = 'pending' and r.pay_hold_by = p.student_id);
      if not ok then res := jsonb_build_object('error', 'Someone else just secured this room. Any money taken will be refunded.'); end if;
    end if;
    if not ok then
      update app.payments set status = 'failed', provider_txn = finalize_payment.provider_txn,
        meta = meta || jsonb_build_object('result', res, 'refund_needed', p.amount > p.savings_used and p.provider <> 'simulated')
       where id = p.id;
      if p.provider <> 'simulated' then
        perform app.note(null, format('Payment %s for %s could not be applied (room no longer free). Refund %s to %s.',
          p.ref, h.title, app.naira(p.amount - p.savings_used), sname));
      end if;
      return res;
    end if;
    start_at := case when b.id is not null then app.ballot_start(b) else t end;
    update app.payments set status = 'held', paid_at = t, provider_txn = finalize_payment.provider_txn where id = p.id;
    if p.savings_used > 0 then
      insert into app.savings_txns(student_id, type, amt, note, payment_id, created_at)
      values (p.student_id, 'applied', p.savings_used, 'Rent · ' || h.title, p.id, t);
    end if;
    insert into app.keys(code, payment_id, house_id, room_id, student_id, start_at, end_at, created_at)
    values (app.gen_key(), p.id, h.id, r.id, p.student_id, start_at, start_at + make_interval(days => c.term_days), t)
    returning * into k;
    update app.rooms set pay_hold_by = null, pay_hold_until = null where id = r.id and pay_hold_by = p.student_id;
    if b.id is not null then
      update app.ballots set status = 'filled', winner_key = k.id where id = b.id;
      update app.rooms set hold_ballot = null where id = r.id;
      perform app.note(e.student_id, format('The ballot for %s has been filled.', h.title))
        from app.ballot_entries e where e.ballot_id = b.id and e.student_id <> p.student_id;
    end if;
    perform app.note(p.student_id, format('Payment confirmed. Your key for %s is ready.', h.title));
    perform app.note(h.agent_id, format('%s paid %s for %s at %s. Lodgely holds it until move-in.',
      sname, app.naira(p.amount), r.name, h.title));
    perform app.note(null, format('%s rent received for %s and held in escrow.', app.naira(p.amount), h.title));
    res := jsonb_build_object('ref', p.ref, 'key', k.code);

  elsif p.kind = 'renewal' then
    select * into k from app.keys where id = (p.meta->>'key_id')::uuid for update;
    select * into r from app.rooms where id = k.room_id;
    if k.status <> 'active' or exists (select 1 from app.ballots where key_id = k.id and status in ('drawn', 'filled')) then
      res := jsonb_build_object('error', 'Renewal closed for this room. Any money taken will be refunded.');
      update app.payments set status = 'failed', meta = meta || jsonb_build_object('result', res,
        'refund_needed', p.amount > p.savings_used and p.provider <> 'simulated') where id = p.id;
      return res;
    end if;
    update app.payments set status = 'released', paid_at = t, released_at = t, provider_txn = finalize_payment.provider_txn where id = p.id;
    if p.savings_used > 0 then
      insert into app.savings_txns(student_id, type, amt, note, payment_id, created_at)
      values (p.student_id, 'applied', p.savings_used, 'Renewal · ' || h.title, p.id, t);
    end if;
    perform app.extend_key(k.id);
    select * into k from app.keys where id = k.id;
    perform app.note(p.student_id, format('Key for %s renewed until %s.', h.title, app.fdate(k.end_at)));
    perform app.note(h.agent_id, format('%s renewed %s at %s. %s paid out after commission.',
      sname, r.name, h.title, app.naira(app.net(p.amount))));
    res := jsonb_build_object('ref', p.ref);

  else -- deposit
    update app.payments set status = 'paid', paid_at = t, provider_txn = finalize_payment.provider_txn where id = p.id;
    insert into app.savings_txns(student_id, type, amt, note, payment_id, created_at)
    values (p.student_id, 'deposit', p.amount, coalesce(nullif(p.method, ''), 'Deposit'), p.id, t);
    res := jsonb_build_object('ref', p.ref);
  end if;

  update app.payments set meta = meta || jsonb_build_object('result', res) where id = p.id;
  perform app.ping(p.student_id);
  if h.id is not null then perform app.ping(h.agent_id); end if;
  return res;
end $$;

-- Renewal: another term on the same key; a running ballot for the room is cancelled.
create or replace function app.extend_key(kid uuid) returns void
language plpgsql as $$
declare k app.keys; b app.ballots; h app.houses; r app.rooms;
begin
  update app.keys set end_at = end_at + make_interval(days => (app.cfg()).term_days), shown = '{}',
         renewals = renewals + 1, not_renewing = false
   where id = kid returning * into k;
  select * into b from app.ballots where key_id = kid and status = 'open';
  if b.id is not null then
    select * into h from app.houses where id = b.house_id;
    select * into r from app.rooms where id = b.room_id;
    update app.ballots set status = 'cancelled' where id = b.id;
    perform app.note(e.student_id, format('The tenant at %s renewed, so the ballot for %s was cancelled.', h.title, r.name))
      from app.ballot_entries e where e.ballot_id = b.id;
    perform app.note(h.agent_id, format('%s renewed, so the ballot for %s at %s was cancelled.', app.pname(k.student_id), r.name, h.title));
  end if;
end $$;

-- Demo / test mode: pretend the provider confirmed the payment.
create or replace function public.simulate_pay(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); p app.payments;
begin
  select * into p from app.payments where ref = a->>'ref' and student_id = u;
  if p.id is null then perform app.fail('Payment not found.'); end if;
  if p.provider <> 'simulated' then perform app.fail('This payment goes through Paystack.'); end if;
  if (a->>'fail')::boolean then
    update app.payments set status = 'failed' where id = p.id and status = 'pending';
    return jsonb_build_object('error', 'The payment did not go through. You have not been charged.');
  end if;
  return app.finalize_payment(p.id, 'SIM-' || p.ref);
end $$;

-- Polling while Paystack checkout is open.
create or replace function public.payment_status(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); p app.payments;
begin
  select * into p from app.payments where ref = a->>'ref' and student_id = u;
  if p.id is null then perform app.fail('Payment not found.'); end if;
  return jsonb_build_object('status', p.status, 'result', p.meta->'result');
end $$;

create or replace function public.cancel_checkout(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login();
begin
  update app.payments set status = 'expired' where ref = a->>'ref' and student_id = u and status = 'pending';
  return '{}'::jsonb;
end $$;

-- Paystack: details the edge function needs to start a transaction (service role only).
create or replace function public.payment_for_provider(p_ref text) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare p app.payments; e text;
begin
  select * into p from app.payments where ref = p_ref;
  if p.id is null then return null; end if;
  select email into e from app.profiles where id = p.student_id;
  return jsonb_build_object('ref', p.ref, 'studentId', p.student_id, 'email', e, 'status', p.status,
    'kind', p.kind, 'chargeKobo', (p.amount - p.savings_used)::bigint * 100);
end $$;

-- Paystack confirmed a charge (webhook or verify). Service role only.
create or replace function public.payment_confirmed(p_ref text, p_amount_kobo bigint, p_txn text, p_channel text)
returns jsonb language plpgsql security definer set search_path = app, public as $$
declare p app.payments;
begin
  select * into p from app.payments where ref = p_ref for update;
  if p.id is null then return jsonb_build_object('error', 'unknown reference'); end if;
  if p.status <> 'pending' then return coalesce(p.meta->'result', jsonb_build_object('ref', p.ref)); end if;
  if p_amount_kobo <> (p.amount - p.savings_used)::bigint * 100 then
    update app.payments set status = 'failed', provider_txn = p_txn,
      meta = meta || jsonb_build_object('refund_needed', true, 'paid_kobo', p_amount_kobo) where id = p.id;
    perform app.note(null, format('Payment %s amount mismatch (got %s kobo). Check and refund.', p.ref, p_amount_kobo));
    return jsonb_build_object('error', 'amount mismatch');
  end if;
  if coalesce(p_channel, '') <> '' then
    update app.payments set method = initcap(replace(p_channel, '_', ' ')) where id = p.id;
  end if;
  return app.finalize_payment(p.id, p_txn);
end $$;

-- >>> db/core/45_student.sql
-- Student actions: saved houses, visits, keys, ballots, savings, complaints.

create or replace function public.toggle_fav(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true); hid uuid := (a->>'houseId')::uuid;
begin
  if exists (select 1 from app.favs where student_id = u and house_id = hid) then
    delete from app.favs where student_id = u and house_id = hid;
    return jsonb_build_object('saved', false);
  end if;
  if not exists (select 1 from app.houses where id = hid and not deleted) then perform app.fail('This house is no longer listed.'); end if;
  insert into app.favs(student_id, house_id, created_at) values (u, hid, app.now());
  return jsonb_build_object('saved', true);
end $$;

-- Student types the 4-digit code the agent shows at the house.
create or replace function public.confirm_visit(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(); i app.inspections; h app.houses;
begin
  select * into i from app.inspections where id = (a->>'id')::uuid and student_id = u for update;
  if i.id is null or i.status <> 'booked' then perform app.fail('This visit is not open any more.'); end if;
  if trim(coalesce(a->>'code', '')) <> i.code then
    perform app.fail('That code does not match. Ask the agent to show the code on their Lodgely app.');
  end if;
  perform app.complete_visit(i.id);
  select * into h from app.houses where id = i.house_id;
  perform app.note(u, format('Visit at %s confirmed. Rent payment is unlocked.', h.title));
  perform app.note(h.agent_id, format('%s confirmed the visit at %s.', app.pname(u), h.title));
  return '{}'::jsonb;
end $$;

create or replace function app.complete_visit(iid uuid) returns void
language plpgsql as $$
declare h app.houses;
begin
  update app.inspections set status = 'completed', done_at = app.now() where id = iid;
  select h2.* into h from app.houses h2 join app.inspections i on i.house_id = h2.id where i.id = iid;
  update app.agents set insp_done = insp_done + 1 where id = h.agent_id;
  perform app.update_trust(h.agent_id);
end $$;

create or replace function public.rate_visit(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true); i app.inspections; ag app.agents; n int := (a->>'n')::int; aid uuid;
begin
  if n is null or n < 1 or n > 5 then perform app.fail('Pick 1 to 5 stars.'); end if;
  select * into i from app.inspections where id = (a->>'id')::uuid and student_id = u for update;
  if i.id is null or i.status <> 'completed' then perform app.fail('You can rate a visit once it is done.'); end if;
  select agent_id into aid from app.houses where id = i.house_id;
  select * into ag from app.agents where id = aid for update;
  if i.rating is not null then
    update app.agents set rating = (rating * ratings - i.rating + n) / greatest(ratings, 1) where id = aid;
  else
    update app.agents set rating = (rating * ratings + n) / (ratings + 1), ratings = ratings + 1 where id = aid;
  end if;
  update app.inspections set rating = n where id = i.id;
  perform app.update_trust(aid);
  select * into ag from app.agents where id = aid;
  perform app.ping(aid);
  return jsonb_build_object('rating', round(ag.rating, 1), 'ratings', ag.ratings, 'trust', ag.trust, 'name', app.first_name(aid));
end $$;

create or replace function public.report_mismatch(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(); i app.inspections; h app.houses; txt text := trim(coalesce(a->>'text', ''));
begin
  if txt = '' then perform app.fail('Describe what was different.'); end if;
  select * into i from app.inspections where id = (a->>'id')::uuid and student_id = u for update;
  if i.id is null then perform app.fail('Visit not found.'); end if;
  if i.mismatch then perform app.fail('You already reported this visit.'); end if;
  select * into h from app.houses where id = i.house_id;
  update app.inspections set mismatch = true where id = i.id;
  update app.agents set mismatches = mismatches + 1 where id = h.agent_id;
  perform app.update_trust(h.agent_id);
  insert into app.complaints(kind, author_id, author_name, author_role, about, house_id, agent_id, body, status, created_at)
  values ('mismatch', u, app.pname(u), 'tenant', 'house', h.id, h.agent_id, txt, 'review', app.now());
  perform app.note(null, format('Listing mismatch reported for %s.', h.title));
  perform app.ping(h.agent_id);
  return '{}'::jsonb;
end $$;

-- Is the visit still more than the cut-off away? (Free to move or cancel with a refund.)
create or replace function app.visit_free(i app.inspections) returns boolean
language sql stable as $$ select i.slot - app.now() > make_interval(hours => (app.cfg()).visit_cut_h) $$;

create or replace function public.reschedule_visit(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(); i app.inspections; h app.houses; v_slot timestamptz := app.ts((a->>'slot')::bigint); t timestamptz := app.now();
begin
  select * into i from app.inspections where id = (a->>'id')::uuid and student_id = u for update;
  if i.id is null or i.status <> 'booked' then perform app.fail('This visit is not open any more.'); end if;
  if i.moves > 0 then perform app.fail('You can move a visit once. Cancel it instead if the new time doesn''t work.'); end if;
  if not app.visit_free(i) then perform app.fail('Visits can''t be moved within 12 hours. You can still cancel.'); end if;
  select * into h from app.houses where id = i.house_id;
  if v_slot is null or v_slot <= t or v_slot > t + interval '15 days'
     or not (to_char(app.wat(v_slot), 'HH24:MI') = any (h.times))
     or not (extract(dow from app.wat(v_slot))::int = any (h.days)) then
    perform app.fail('That time is no longer available. Pick another slot.');
  end if;
  update app.inspections set slot = v_slot, moves = moves + 1, r24 = false, r1 = false where id = i.id;
  perform app.note(h.agent_id, format('%s moved their visit at %s to %s.', app.pname(u), h.title, app.fslot(v_slot)));
  return jsonb_build_object('slot', app.ms(v_slot));
end $$;

create or replace function public.cancel_visit(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true); i app.inspections; h app.houses; free boolean;
begin
  select * into i from app.inspections where id = (a->>'id')::uuid and student_id = u for update;
  if i.id is null or i.status <> 'booked' then perform app.fail('This visit is not open any more.'); end if;
  free := app.visit_free(i);
  select * into h from app.houses where id = i.house_id;
  update app.inspections set status = 'stuCancelled', refunded = free where id = i.id;
  if free then perform app.refund_payment_row(i.payment_id); end if;
  perform app.note(h.agent_id, format('%s cancelled the visit to %s on %s.%s', app.pname(u), h.title, app.fslot(i.slot),
    case when free then ' The fee was refunded.' else ' You keep the fee.' end));
  return jsonb_build_object('refunded', free);
end $$;

-- Mark a payment refunded (money goes back through the provider; admin sees it in Payments).
create or replace function app.refund_payment_row(pid uuid) returns void
language plpgsql as $$
declare p app.payments;
begin
  select * into p from app.payments where id = pid for update;
  if p.id is null or p.status = 'refunded' then return; end if;
  update app.payments set status = 'refunded', refunded_at = app.now(),
    meta = meta || case when p.provider = 'paystack' then jsonb_build_object('refund_needed', true) else '{}'::jsonb end
   where id = pid;
  if p.savings_used > 0 then
    insert into app.savings_txns(student_id, type, amt, note, payment_id, created_at)
    values (p.student_id, 'deposit', p.savings_used, 'Refund returned to savings', p.id, app.now());
  end if;
  perform app.ping(p.student_id);
end $$;

create or replace function public.report_no_show(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true); i app.inspections; h app.houses; ag app.agents;
begin
  select * into i from app.inspections where id = (a->>'id')::uuid and student_id = u for update;
  if i.id is null or i.status <> 'booked' then perform app.fail('This visit is not open any more.'); end if;
  if i.slot > app.now() then perform app.fail('You can report a no-show once the visit time has passed.'); end if;
  select * into h from app.houses where id = i.house_id;
  update app.inspections set status = 'noshow' where id = i.id;
  perform app.refund_payment_row(i.payment_id);
  update app.agents set no_shows = no_shows + 1 where id = h.agent_id;
  perform app.update_trust(h.agent_id);
  select * into ag from app.agents where id = h.agent_id;
  perform app.note(h.agent_id, format('%s reported that you missed the visit at %s. The fee was refunded and your trust score dropped.', app.pname(u), h.title));
  perform app.note(null, format('No-show reported against %s at %s.', app.pname(h.agent_id), h.title));
  return jsonb_build_object('trust', ag.trust, 'name', app.first_name(h.agent_id));
end $$;

create or replace function public.join_ballot(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(); b app.ballots; h app.houses; r app.rooms;
begin
  select * into b from app.ballots where id = (a->>'id')::uuid for update;
  if b.id is null or b.status <> 'open' then perform app.fail('This ballot is closed.'); end if;
  if not app.insp_done(u, b.house_id) then perform app.fail('Inspect the house first. Only students who inspected can enter.'); end if;
  if exists (select 1 from app.keys where id = b.key_id and student_id = u) then perform app.fail('This is your own room. Renew it instead.'); end if;
  select * into h from app.houses where id = b.house_id;
  select * into r from app.rooms where id = b.room_id;
  insert into app.ballot_entries(ballot_id, student_id, created_at) values (b.id, u, app.now()) on conflict do nothing;
  perform app.note(h.agent_id, format('%s joined the ballot for %s at %s.', app.pname(u), r.name, h.title));
  return jsonb_build_object('drawAt', app.ms(b.draw_at));
end $$;

create or replace function public.leave_ballot(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true);
begin
  delete from app.ballot_entries e using app.ballots b
   where e.ballot_id = b.id and b.id = (a->>'id')::uuid and b.status = 'open' and e.student_id = u;
  return '{}'::jsonb;
end $$;

-- Open a ballot for a key's room. Demo mode adds a few sample entrants so the draw has people in it.
create or replace function app.open_ballot(kid uuid, draw timestamptz) returns app.ballots
language plpgsql as $$
declare k app.keys; b app.ballots;
begin
  select * into k from app.keys where id = kid;
  insert into app.ballots(house_id, room_id, key_id, draw_at, created_at)
  values (k.house_id, k.room_id, k.id, draw, app.now()) returning * into b;
  if (app.cfg()).demo then
    insert into app.ballot_entries(ballot_id, student_id, created_at)
    select b.id, p.id, app.now() from app.profiles p
     where p.role = 'student' and p.id <> k.student_id and p.id <> app.sid('s1') and not p.suspended
       and not exists (select 1 from app.keys x where x.student_id = p.id and x.status = 'active')
     order by random() limit 2 + floor(random() * 4)::int;
  end if;
  return b;
end $$;

create or replace function public.not_renewing(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true); k app.keys; b app.ballots; h app.houses; r app.rooms; draw timestamptz;
begin
  select * into k from app.keys where code = a->>'code' and student_id = u and status = 'active' for update;
  if k.id is null then perform app.fail('This key is no longer active.'); end if;
  update app.keys set not_renewing = true where id = k.id;
  draw := least(k.end_at, app.now() + interval '2 days');
  select * into b from app.ballots where key_id = k.id and status = 'open';
  if b.id is null then b := app.open_ballot(k.id, draw); end if;
  update app.ballots set draw_at = draw where id = b.id;
  select * into h from app.houses where id = k.house_id;
  select * into r from app.rooms where id = k.room_id;
  perform app.note(h.agent_id, format('%s is not renewing %s at %s. The ballot draw is on %s.', app.pname(u), r.name, h.title, app.fdate(draw)));
  return jsonb_build_object('drawAt', app.ms(draw));
end $$;

create or replace function public.toggle_auto_renew(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true); on_ boolean;
begin
  update app.keys set auto_renew = not auto_renew where code = a->>'code' and student_id = u and status = 'active'
  returning auto_renew into on_;
  if on_ is null then perform app.fail('This key is no longer active.'); end if;
  return jsonb_build_object('on', on_);
end $$;

-- Release held rent to the agent.
create or replace function app.release_key(kid uuid, reason text) returns void
language plpgsql as $$
declare k app.keys; p app.payments; h app.houses; r app.rooms;
begin
  select * into k from app.keys where id = kid;
  select * into p from app.payments where id = k.payment_id for update;
  select * into h from app.houses where id = k.house_id;
  select * into r from app.rooms where id = k.room_id;
  if reason <> 'Auto-released after 7 days' then update app.keys set moved_in = true where id = kid; end if;
  if p.id is not null and p.status = 'held' then
    update app.payments set status = 'released', released_at = app.now() where id = p.id;
    perform app.note(h.agent_id, format('%s released to you for %s at %s after %s%% commission. %s.',
      app.naira(app.net(p.amount)), r.name, h.title, round((app.cfg()).commission * 100), reason));
  end if;
end $$;

create or replace function public.confirm_move_in(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true); k app.keys;
begin
  select * into k from app.keys where code = a->>'code' and student_id = u and status = 'active' for update;
  if k.id is null then perform app.fail('This key is no longer active.'); end if;
  perform app.release_key(k.id, 'Move-in confirmed by the tenant');
  update app.keys set moved_in = true where id = k.id;
  return '{}'::jsonb;
end $$;

create or replace function public.raise_dispute(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(true); k app.keys; h app.houses; txt text := trim(coalesce(a->>'text', '')); why text := coalesce(nullif(a->>'reason', ''), 'Something else');
begin
  if txt = '' then perform app.fail('Describe what went wrong.'); end if;
  select * into k from app.keys where code = a->>'code' and student_id = u;
  if k.id is null then perform app.fail('Key not found.'); end if;
  select * into h from app.houses where id = k.house_id;
  insert into app.complaints(kind, author_id, author_name, author_role, about, house_id, agent_id, reason, payment_id, body, status, created_at)
  values ('dispute', u, app.pname(u), 'tenant', 'house', h.id, h.agent_id, why, k.payment_id, txt, 'open', app.now());
  perform app.note(null, format('New dispute from %s about %s: %s.', app.pname(u), h.title, why));
  perform app.note(h.agent_id, format('%s raised a dispute about %s. Lodgely will review the chat and payment.', app.pname(u), h.title));
  return '{}'::jsonb;
end $$;

-- Public complaint by a student about a house or its agent.
create or replace function public.post_complaint(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(); h app.houses; txt text := trim(coalesce(a->>'text', '')); about text := coalesce(a->>'about', 'house');
begin
  if txt = '' then perform app.fail('Write what happened before posting.'); end if;
  if about not in ('house', 'agent') then about := 'house'; end if;
  select * into h from app.houses where id = (a->>'houseId')::uuid;
  if h.id is null then perform app.fail('House not found.'); end if;
  insert into app.complaints(kind, author_id, author_name, author_role, about, house_id, agent_id, body, status, created_at)
  values ('public', u, app.short_name(u),
          case when exists (select 1 from app.keys where student_id = u and house_id = h.id) then 'tenant' else 'student' end,
          about, h.id, h.agent_id, txt, 'open', app.now());
  perform app.note(h.agent_id, format('%s posted a complaint about %s. You can reply from Account.', app.short_name(u),
    case when about = 'agent' then 'you' else h.title end));
  perform app.note(null, format('New public complaint about %s.', h.title));
  return '{}'::jsonb;
end $$;

-- Right of reply: the agent (about their house) or the tenant (about them).
create or replace function public.reply_complaint(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); cp app.complaints; txt text := trim(coalesce(a->>'text', ''));
begin
  if txt = '' then perform app.fail('Write a reply first.'); end if;
  select * into cp from app.complaints where id = (a->>'id')::uuid for update;
  if cp.id is null then perform app.fail('Complaint not found.'); end if;
  if not (cp.agent_id = u and cp.about <> 'tenant') and not (cp.tenant_id = u and cp.about = 'tenant') then
    perform app.fail('Only the person this complaint is about can reply.');
  end if;
  update app.complaints set reply = txt, reply_by = app.pname(u) where id = cp.id;
  if cp.tenant_id = u then perform app.note(cp.agent_id, format('%s replied to your complaint about them.', app.pname(u))); end if;
  if cp.author_id is not null and cp.author_id <> u then perform app.ping(cp.author_id); end if;
  return '{}'::jsonb;
end $$;

-- Savings goal. a = {name, target, due:'YYYY-MM-DD', mode, sched, schedAmt}
create or replace function public.save_goal(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare
  u uuid := app.need_student(true); g0 app.savings_goals; t timestamptz := app.now();
  nm text := trim(coalesce(a->>'name', '')); tg int := nullif(regexp_replace(coalesce(a->>'target', ''), '\D', '', 'g'), '')::int;
  v_due date; v_mode text := coalesce(a->>'mode', 'flexible'); v_sched text := coalesce(a->>'sched', 'none');
  amt int := coalesce(nullif(regexp_replace(coalesce(a->>'schedAmt', ''), '\D', '', 'g'), '')::int, 0);
  locked boolean; nxt timestamptz;
begin
  begin v_due := (a->>'due')::date; exception when others then v_due := null; end;
  if nm = '' or coalesce(tg, 0) <= 0 or v_due is null then perform app.fail('Add a name, a target and a due date.'); end if;
  if v_mode not in ('flexible', 'locked') then v_mode := 'flexible'; end if;
  if v_sched not in ('none', 'weekly', 'monthly') then v_sched := 'none'; end if;
  select * into g0 from app.savings_goals where student_id = u;
  locked := g0.mode = 'locked' and t < g0.due::timestamp;
  if locked and v_mode <> 'locked' then
    perform app.fail(format('Your savings are locked until %s. You can switch to flexible after that date.', trim(to_char(g0.due, 'FMDD Mon YYYY'))));
  end if;
  if locked and v_due < g0.due then
    perform app.fail(format('While your savings are locked, the due date can move later than %s, not earlier.', trim(to_char(g0.due, 'FMDD Mon YYYY'))));
  end if;
  nxt := case when v_sched = 'none' or amt = 0 then null
              when g0.student_id is null or v_sched is distinct from g0.sched or g0.next_auto is null
                then t + make_interval(days => case when v_sched = 'weekly' then 7 else 30 end)
              else g0.next_auto end;
  insert into app.savings_goals(student_id, name, target, due, mode, sched, sched_amt, next_auto)
  values (u, nm, tg, v_due, v_mode, v_sched, amt, nxt)
  on conflict (student_id) do update set name = excluded.name, target = excluded.target, due = excluded.due,
    mode = excluded.mode, sched = excluded.sched, sched_amt = excluded.sched_amt, next_auto = excluded.next_auto;
  return '{}'::jsonb;
end $$;

create or replace function public.withdraw_savings(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(); amt int := nullif(regexp_replace(coalesce(a->>'amount', ''), '\D', '', 'g'), '')::int;
  bal int; g app.savings_goals;
begin
  select * into g from app.savings_goals where student_id = u;
  if g.mode = 'locked' and app.now() < g.due::timestamp then
    perform app.fail(format('Your savings are locked until %s.', trim(to_char(g.due, 'FMDD Mon YYYY'))));
  end if;
  perform 1 from app.profiles where id = u for update;  -- one withdrawal at a time
  bal := app.savings_balance(u);
  if coalesce(amt, 0) <= 0 or amt > bal then perform app.fail(format('Enter an amount up to %s.', app.naira(bal))); end if;
  insert into app.savings_txns(student_id, type, amt, note, created_at)
  values (u, 'withdrawal', amt, coalesce(nullif(a->>'to', ''), 'To your bank or wallet'), app.now());
  perform app.note(null, format('Savings withdrawal of %s requested by %s. Send it to their account.', app.naira(amt), app.pname(u)));
  return jsonb_build_object('amount', amt);
end $$;

-- >>> db/core/50_agent.sql
-- Agent actions: listings, rooms, visits, payouts, verification documents.

-- Create or edit a listing. a = {editId, title, area, address, km, type, desc, amenities[], rules[],
--   shared, photos[], times[], days[], baths, availFrom, furnished, rooms:[{id, name, price, cap}]}
create or replace function public.save_listing(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare
  u uuid := app.need_agent(true); h app.houses; ex app.rooms; t timestamptz := app.now();
  v_title text := trim(coalesce(a->>'title', '')); v_address text := trim(coalesce(a->>'address', ''));
  v_shared boolean := coalesce((a->>'shared')::boolean, false); furn boolean := coalesce((a->>'furnished')::boolean, false);
  v_times text[]; v_days int[]; v_photos text[]; rr jsonb; keep uuid[] := '{}'; nm text; pr int; cp int; n int := 0;
  was_rejected boolean; i int := 0;
begin
  if v_title = '' or v_address = '' then perform app.fail('Add a house name, a street address and at least one room with a price.'); end if;
  select array_agg(x order by x) into v_times from jsonb_array_elements_text(coalesce(a->'times', '[]')) x where x ~ '^\d{2}:\d{2}$';
  select array_agg(x::int order by x::int) into v_days from jsonb_array_elements_text(coalesce(a->'days', '[]')) x where x ~ '^[0-6]$';
  if coalesce(array_length(v_times, 1), 0) = 0 or coalesce(array_length(v_days, 1), 0) = 0 then
    perform app.fail('Pick at least one day and one time for inspections.');
  end if;
  select coalesce(array_agg(x), '{}') into v_photos from (select x from jsonb_array_elements_text(coalesce(a->'photos', '[]')) x limit 8) s;
  select count(*) into n from jsonb_array_elements(coalesce(a->'rooms', '[]')) r
   where trim(coalesce(r->>'name', '')) <> '' and coalesce(nullif(regexp_replace(coalesce(r->>'price', ''), '\D', '', 'g'), '')::numeric, 0) > 0;
  if n = 0 then perform app.fail('Add a house name, a street address and at least one room with a price.'); end if;

  if nullif(a->>'editId', '') is not null then
    select * into h from app.houses where id = (a->>'editId')::uuid and agent_id = u and not deleted for update;
    if h.id is null then perform app.fail('Listing not found.'); end if;
    was_rejected := h.mod = 'rejected';
    update app.houses set title = v_title, area = coalesce(a->>'area', area), address = v_address,
      km = coalesce((a->>'km')::numeric, km), type = coalesce(a->>'type', type), descr = coalesce(nullif(trim(a->>'desc'), ''), 'No description yet.'),
      amenities = coalesce(array(select jsonb_array_elements_text(a->'amenities')), '{}'),
      rules = coalesce(array(select jsonb_array_elements_text(a->'rules')), '{}'),
      shared = v_shared, photos = v_photos, times = v_times, days = v_days,
      baths = greatest(1, least(30, coalesce((a->>'baths')::int, 1))), avail_from = nullif(a->>'availFrom', '')::date,
      mod = case when was_rejected then 'pending' else mod end
     where id = h.id;
    for rr in select * from jsonb_array_elements(coalesce(a->'rooms', '[]')) loop
      i := i + 1;
      nm := trim(coalesce(rr->>'name', ''));
      pr := nullif(regexp_replace(coalesce(rr->>'price', ''), '\D', '', 'g'), '')::int;
      cp := greatest(1, least(6, coalesce((rr->>'cap')::int, 1)));
      ex := null;
      if nullif(rr->>'id', '') is not null then
        select * into ex from app.rooms where id = (rr->>'id')::uuid and house_id = h.id;
      end if;
      if ex.id is not null then
        update app.rooms set name = coalesce(nullif(nm, ''), name), price = case when coalesce(pr, 0) > 0 then pr else price end,
          cap = case when v_shared then greatest(greatest(1, app.active_count(id)), cp) else greatest(1, app.active_count(id)) end,
          furnished = furn, sort = i, archived = false
         where id = ex.id;
        keep := keep || ex.id;
      elsif nm <> '' and coalesce(pr, 0) > 0 then
        insert into app.rooms(house_id, name, price, cap, furnished, sort)
        values (h.id, nm, pr, case when v_shared then cp else 1 end, furn, i) returning id into ex.id;
        keep := keep || ex.id;
      end if;
    end loop;
    -- rooms left out: archive, unless someone lives there or a ballot is running
    update app.rooms r set archived = true
     where r.house_id = h.id and not (r.id = any (keep)) and not r.archived
       and app.active_count(r.id) = 0 and r.hold_ballot is null
       and not exists (select 1 from app.ballots b where b.room_id = r.id and b.status in ('open', 'drawn'));
    perform app.note(null, format('%s %s %s.', app.pname(u), case when was_rejected then 'resubmitted' else 'edited' end, v_title));
    select * into h from app.houses where id = h.id;
    return jsonb_build_object('id', h.id, 'mod', h.mod, 'resubmitted', was_rejected);
  end if;

  insert into app.houses(agent_id, title, area, address, km, type, descr, amenities, rules, shared, photos, times, days, baths, avail_from, art, mod, created_at)
  values (u, v_title, coalesce(a->>'area', 'Damico'), v_address, coalesce((a->>'km')::numeric, 1), coalesce(a->>'type', 'Self-contain'),
    coalesce(nullif(trim(a->>'desc'), ''), 'No description yet.'),
    coalesce(array(select jsonb_array_elements_text(a->'amenities')), '{}'),
    coalesce(array(select jsonb_array_elements_text(a->'rules')), '{}'),
    v_shared, v_photos, v_times, v_days, greatest(1, least(30, coalesce((a->>'baths')::int, 1))), nullif(a->>'availFrom', '')::date,
    jsonb_build_object('wall', floor(random() * 7)::int, 'roof', floor(random() * 5)::int,
                       'kind', (array['bungalow', 'storey', 'flats'])[1 + floor(random() * 3)::int]),
    'pending', t)
  returning * into h;
  for rr in select * from jsonb_array_elements(coalesce(a->'rooms', '[]')) loop
    nm := trim(coalesce(rr->>'name', ''));
    pr := nullif(regexp_replace(coalesce(rr->>'price', ''), '\D', '', 'g'), '')::int;
    if nm <> '' and coalesce(pr, 0) > 0 then
      i := i + 1;
      insert into app.rooms(house_id, name, price, cap, furnished, sort)
      values (h.id, nm, pr, case when v_shared then greatest(1, least(6, coalesce((rr->>'cap')::int, 1))) else 1 end, furn, i);
    end if;
  end loop;
  perform app.note(null, format('New listing awaiting review: %s.', v_title));
  return jsonb_build_object('id', h.id, 'mod', 'pending');
end $$;

create or replace function app.my_house(hid uuid, u uuid) returns app.houses
language plpgsql stable as $$
declare h app.houses;
begin
  select * into h from app.houses where id = hid and agent_id = u and not deleted;
  if h.id is null then perform app.fail('Listing not found.'); end if;
  return h;
end $$;

create or replace function public.toggle_room_pause(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(true); h app.houses := app.my_house((a->>'houseId')::uuid, u); p boolean;
begin
  update app.rooms set paused = not paused where id = (a->>'roomId')::uuid and house_id = h.id returning paused into p;
  return jsonb_build_object('paused', p);
end $$;

create or replace function public.toggle_shared(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(true); h app.houses := app.my_house((a->>'houseId')::uuid, u); on_ boolean := not h.shared;
begin
  update app.houses set shared = on_ where id = h.id;
  if on_ then
    update app.rooms set cap = greatest(cap_saved, app.active_count(id)) where house_id = h.id and coalesce(cap_saved, 1) > 1;
  else
    update app.rooms set cap_saved = cap, cap = greatest(1, app.active_count(id)) where house_id = h.id and cap > 1;
  end if;
  return jsonb_build_object('shared', on_);
end $$;

create or replace function public.set_room_cap(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(true); h app.houses := app.my_house((a->>'houseId')::uuid, u); r app.rooms; n int;
begin
  if not h.shared then perform app.fail('Turn on shared rooms first.'); end if;
  select * into r from app.rooms where id = (a->>'roomId')::uuid and house_id = h.id for update;
  n := greatest(greatest(1, app.active_count(r.id)), least(6, r.cap + coalesce((a->>'d')::int, 0)));
  if n = r.cap then
    perform app.fail(case when r.cap >= 6 then 'A room can have at most 6 spaces.' else 'You cannot go below the tenants already in this room.' end);
  end if;
  update app.rooms set cap = n, cap_saved = n where id = r.id;
  return jsonb_build_object('cap', n);
end $$;

create or replace function public.toggle_listing_pause(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(true); h app.houses := app.my_house((a->>'id')::uuid, u); p boolean := not h.paused;
begin
  update app.houses set paused = p where id = h.id;
  perform app.note(null, format('%s %s %s.', app.pname(u), case when p then 'paused' else 'resumed' end, h.title));
  return jsonb_build_object('paused', p);
end $$;

-- What stops a listing from being deleted right now (empty = nothing).
create or replace function app.listing_busy(hid uuid) returns text[]
language sql stable as $$
  select array_remove(array[
    case when exists (select 1 from app.keys where house_id = hid and status = 'active') then 'current or upcoming tenants' end,
    case when exists (select 1 from app.inspections where house_id = hid and status = 'booked') then 'booked visits' end,
    case when exists (select 1 from app.ballots where house_id = hid and status in ('open', 'drawn')) then 'a running ballot' end
  ], null)
$$;

create or replace function public.delete_listing(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(true); h app.houses := app.my_house((a->>'id')::uuid, u); busy text[] := app.listing_busy(h.id);
begin
  if array_length(busy, 1) > 0 then perform app.fail('This listing still has ' || array_to_string(busy, ', ') || '.'); end if;
  update app.houses set deleted = true, paused = true, mod = 'deleted' where id = h.id;
  delete from app.favs where house_id = h.id;
  perform app.note(null, format('%s deleted %s.', app.pname(u), h.title));
  return '{}'::jsonb;
end $$;

-- Agent marks a visit done (the student did not enter the code).
create or replace function public.agent_complete_visit(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(); i app.inspections; h app.houses;
begin
  select i2.* into i from app.inspections i2 join app.houses h2 on h2.id = i2.house_id
   where i2.id = (a->>'id')::uuid and h2.agent_id = u for update of i2;
  if i.id is null or i.status <> 'booked' then perform app.fail('This visit is not open any more.'); end if;
  if i.slot > app.now() + interval '1 hour' then perform app.fail('You can mark a visit as done from an hour before it starts.'); end if;
  perform app.complete_visit(i.id);
  select * into h from app.houses where id = i.house_id;
  perform app.note(i.student_id, format('%s marked your visit at %s as done. Rent payment is unlocked.', app.pname(u), h.title));
  return '{}'::jsonb;
end $$;

create or replace function public.agent_cancel_visit(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(true); i app.inspections; h app.houses;
begin
  select i2.* into i from app.inspections i2 join app.houses h2 on h2.id = i2.house_id
   where i2.id = (a->>'id')::uuid and h2.agent_id = u for update of i2;
  if i.id is null or i.status <> 'booked' then perform app.fail('This visit is not open any more.'); end if;
  select * into h from app.houses where id = i.house_id;
  update app.inspections set status = 'cancelled', refunded = true where id = i.id;
  perform app.refund_payment_row(i.payment_id);
  update app.agents set cancels = cancels + 1 where id = u;
  perform app.update_trust(u);
  perform app.note(i.student_id, format('%s cancelled your visit at %s. %s refunded.', app.pname(u), h.title, app.naira(i.fee)));
  return '{}'::jsonb;
end $$;

create or replace function public.mark_missed(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(); i app.inspections; h app.houses;
begin
  select i2.* into i from app.inspections i2 join app.houses h2 on h2.id = i2.house_id
   where i2.id = (a->>'id')::uuid and h2.agent_id = u for update of i2;
  if i.id is null or i.status <> 'booked' then perform app.fail('This visit is not open any more.'); end if;
  if i.slot > app.now() then perform app.fail('You can mark a student as missing once the visit time has passed.'); end if;
  select * into h from app.houses where id = i.house_id;
  update app.inspections set status = 'missed' where id = i.id;
  perform app.note(i.student_id, format('%s marked that you missed your visit to %s. The fee is not refunded. You can book another visit.', app.pname(u), h.title));
  return '{}'::jsonb;
end $$;

-- Agent posts a public complaint about one of their tenants.
create or replace function public.post_tenant_complaint(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(); k app.keys; h app.houses; txt text := trim(coalesce(a->>'text', ''));
begin
  select k2.* into k from app.keys k2 join app.houses h2 on h2.id = k2.house_id where k2.code = a->>'code' and h2.agent_id = u;
  if k.id is null or txt = '' then perform app.fail('Choose a tenant and write what happened.'); end if;
  select * into h from app.houses where id = k.house_id;
  insert into app.complaints(kind, author_id, author_name, author_role, about, house_id, agent_id, tenant_id, tenant_name, body, status, created_at)
  values ('public', u, app.short_name(u), 'owner', 'tenant', h.id, u, k.student_id, app.pname(k.student_id), txt, 'open', app.now());
  perform app.note(null, format('New complaint about tenant %s.', app.pname(k.student_id)));
  perform app.note(k.student_id, format('%s posted a public complaint about you. You can reply from My lodge.', app.pname(u)));
  return '{}'::jsonb;
end $$;

-- Payout account. In simulated mode the account name is the agent's own name;
-- with Paystack the paystack-resolve edge function checks it with the bank first.
create or replace function public.check_payout(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(true); acct text := regexp_replace(coalesce(a->>'acct', ''), '\D', '', 'g');
begin
  if length(acct) <> 10 then perform app.fail('Enter the 10-digit account number.'); end if;
  if (app.cfg()).payment_mode = 'paystack' then perform app.fail('Use the bank check in the app.'); end if;
  return jsonb_build_object('name', upper(app.pname(u)));
end $$;

create or replace function public.save_payout(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_agent(true); acct text := regexp_replace(coalesce(a->>'acct', ''), '\D', '', 'g'); bank text := trim(coalesce(a->>'bank', ''));
begin
  if length(acct) <> 10 or bank = '' then perform app.fail('Enter the bank and the 10-digit account number.'); end if;
  if (app.cfg()).payment_mode = 'paystack' then perform app.fail('Use the bank check in the app.'); end if;
  perform app.set_payout(u, bank, acct, upper(app.pname(u)));
  return '{}'::jsonb;
end $$;

create or replace function app.set_payout(u uuid, bank text, acct text, nm text) returns void
language plpgsql as $$
begin
  update app.agents set payout_bank = bank, payout_acct = acct, payout_name = nm where id = u;
  perform app.note(u, format('Your payout account was changed to %s •••• %s. If this wasn''t you, contact Lodgely support.', bank, right(acct, 4)));
end $$;

-- Called by the paystack-resolve edge function (service role only) after the bank confirmed the name.
create or replace function public.set_payout_verified(p_agent uuid, p_bank text, p_acct text, p_name text) returns jsonb
language plpgsql security definer set search_path = app, public as $$
begin
  if app.role_of(p_agent) <> 'agent' then return jsonb_build_object('error', 'not an agent'); end if;
  perform app.set_payout(p_agent, p_bank, p_acct, p_name);
  return '{}'::jsonb;
end $$;

-- Verification documents (first time, or after admin asked for changes).
-- a = {idType, idFile, proofType, proofFile, btype, rel, files:[storage paths]}
create or replace function public.submit_agent_docs(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); ag app.agents; p app.profiles; lines jsonb; resub boolean;
begin
  if app.role_of(u) <> 'agent' then perform app.fail('Only agents can do this.'); end if;
  if coalesce(a->>'idFile', '') = '' then perform app.fail('Upload your ID document.'); end if;
  if coalesce(a->>'proofFile', '') = '' then perform app.fail('Upload proof that you can let the property.'); end if;
  select * into ag from app.agents where id = u for update;
  select * into p from app.profiles where id = u;
  if ag.status in ('verified', 'suspended') then perform app.fail('Your account is already reviewed.'); end if;
  resub := jsonb_array_length(ag.docs) > 0;
  lines := jsonb_build_array(
    'Business type: ' || coalesce(nullif(a->>'btype', ''), ag.btype, 'Not given'),
    'Relationship to the property: ' || coalesce(nullif(a->>'rel', ''), ag.rel, 'Not given'),
    case when p.phone is not null then 'Phone ' || p.phone else 'No phone given' end,
    'Email ' || coalesce(p.email, 'not given') || ' confirmed by code',
    (a->>'idType') || ': ' || (a->>'idFile'),
    (a->>'proofType') || ': ' || (a->>'proofFile'));
  update app.agents set docs = lines, doc_files = coalesce(a->'files', '[]'::jsonb),
    btype = coalesce(nullif(a->>'btype', ''), btype), rel = coalesce(nullif(a->>'rel', ''), rel),
    status = 'pending', reject_reason = null
   where id = u;
  perform app.note(null, case when resub then format('%s sent new verification documents.', p.name)
                              else format('%s applied to list houses on Lodgely.', p.name) end);
  return jsonb_build_object('resubmitted', resub);
end $$;

-- >>> db/core/55_admin.sql
-- Admin actions: verification, moderation, money, complaints, support.

create or replace function public.approve_agent(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); aid uuid := (a->>'id')::uuid;
begin
  update app.agents set status = 'verified', verified_at = app.now(), resp = 'new agent', reject_reason = null where id = aid;
  if not found then perform app.fail('Agent not found.'); end if;
  perform app.update_trust(aid);
  perform app.note(aid, 'Your account is verified.');
  return jsonb_build_object('name', app.pname(aid));
end $$;

create or replace function public.reject_agent(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); aid uuid := (a->>'id')::uuid;
  why text := coalesce(nullif(a->>'reason', ''), 'Documents unclear') || coalesce('. ' || nullif(trim(a->>'note'), ''), '');
begin
  update app.agents set status = 'rejected', reject_reason = why where id = aid;
  if not found then perform app.fail('Agent not found.'); end if;
  perform app.note(aid, format('Your verification needs changes: %s. Upload new documents from your application screen.', why));
  return jsonb_build_object('name', app.pname(aid));
end $$;

create or replace function public.approve_listing(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); h app.houses; st text;
begin
  update app.houses set mod = 'live', created_at = app.now() where id = (a->>'id')::uuid and mod in ('pending', 'rejected') returning * into h;
  if h.id is null then perform app.fail('Listing not found.'); end if;
  select status into st from app.agents where id = h.agent_id;
  perform app.note(h.agent_id, format('%s is live.', h.title));
  return jsonb_build_object('title', h.title, 'agentVerified', st = 'verified');
end $$;

create or replace function public.reject_listing(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); h app.houses;
begin
  update app.houses set mod = 'rejected' where id = (a->>'id')::uuid and mod = 'pending' returning * into h;
  if h.id is null then perform app.fail('Listing not found.'); end if;
  perform app.note(h.agent_id, format('%s was not approved.%s', h.title, coalesce(' ' || nullif(trim(a->>'note'), ''), '')));
  return '{}'::jsonb;
end $$;

-- Cancel booked visits matching a house or agent and refund them.
create or replace function app.cancel_visits_for(hid uuid, aid uuid, why text) returns int
language plpgsql as $$
declare i record; n int := 0;
begin
  for i in select i2.* from app.inspections i2 join app.houses h on h.id = i2.house_id
            where i2.status = 'booked' and (h.id = hid or h.agent_id = aid) for update of i2 loop
    update app.inspections set status = 'cancelled', by_admin = true, refunded = true where id = i.id;
    perform app.refund_payment_row(i.payment_id);
    perform app.note(i.student_id, format('%s, so your visit on %s was cancelled and your %s refunded.', why, app.fslot(i.slot), app.naira(i.fee)));
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.take_down_listing(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); h app.houses; nv int; why text := coalesce(nullif(a->>'reason', ''), 'Something else');
  nt text := nullif(trim(coalesce(a->>'note', '')), ''); b record;
begin
  update app.houses set mod = 'removed', removed_reason = why, removed_note = nt, removed_at = app.now()
   where id = (a->>'id')::uuid returning * into h;
  if h.id is null then perform app.fail('Listing not found.'); end if;
  nv := app.cancel_visits_for(h.id, null, format('Lodgely took down %s', h.title));
  for b in select * from app.ballots where house_id = h.id and status = 'open' loop
    update app.ballots set status = 'cancelled' where id = b.id;
    perform app.note(e.student_id, format('The ballot at %s was cancelled because the listing was taken down.', h.title))
      from app.ballot_entries e where e.ballot_id = b.id;
  end loop;
  perform app.note(h.agent_id, format('Lodgely took down %s: %s.%s Current tenants are not affected. Contact support to appeal.',
    h.title, why, coalesce(' ' || nt, '')));
  return jsonb_build_object('visits', nv, 'title', h.title);
end $$;

create or replace function public.restore_listing(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); h app.houses;
begin
  update app.houses set mod = 'live', removed_reason = null, removed_note = null where id = (a->>'id')::uuid and mod = 'removed' returning * into h;
  if h.id is null then perform app.fail('Listing not found.'); end if;
  perform app.note(h.agent_id, format('%s is live again.', h.title));
  return jsonb_build_object('title', h.title);
end $$;

-- a = {k:'agent'|'student', id, reason, note}
create or replace function public.suspend_user(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); id_ uuid := (a->>'id')::uuid; nv int := 0;
  why text := coalesce(nullif(a->>'reason', ''), 'Something else') || coalesce('. ' || nullif(trim(a->>'note'), ''), '');
begin
  if a->>'k' = 'agent' then
    update app.agents set status = 'suspended', suspend_reason = why where id = id_;
    if not found then perform app.fail('Agent not found.'); end if;
    nv := app.cancel_visits_for(null, id_, format('%s is no longer taking visits', app.pname(id_)));
    perform app.note(id_, format('Your Lodgely account is suspended: %s. Your houses are hidden from students. Contact support to appeal.', why));
  else
    update app.profiles set suspended = true, suspend_reason = why where id = id_ and role = 'student';
    if not found then perform app.fail('Student not found.'); end if;
    delete from app.ballot_entries e using app.ballots b where e.ballot_id = b.id and b.status = 'open' and e.student_id = id_;
    update app.rooms set pay_hold_by = null, pay_hold_until = null where pay_hold_by = id_;
    perform app.note(id_, format('Your Lodgely account is suspended: %s. You can see your key and payments, but you can''t book, pay or message. Contact support to appeal.', why));
  end if;
  return jsonb_build_object('name', app.pname(id_), 'visits', nv);
end $$;

create or replace function public.restore_user(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); id_ uuid := (a->>'id')::uuid;
begin
  if a->>'k' = 'agent' then
    update app.agents set status = 'verified', suspend_reason = null where id = id_;
    perform app.note(id_, 'Your Lodgely account is active again. Your houses are back in search.');
  else
    update app.profiles set suspended = false, suspend_reason = null where id = id_;
    perform app.note(id_, 'Your Lodgely account is active again.');
  end if;
  return jsonb_build_object('name', app.pname(id_));
end $$;

create or replace function public.review_report(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); st text;
begin
  update app.threads set report_status = case when report_status = 'reviewed' then 'open' else 'reviewed' end
   where id = (a->>'id')::uuid returning report_status into st;
  return jsonb_build_object('status', st);
end $$;

-- Release held money to the agent now.
create or replace function public.release_payment(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); p app.payments; kid uuid;
begin
  select * into p from app.payments where id = (a->>'id')::uuid for update;
  if p.id is null then perform app.fail('Payment not found.'); end if;
  select id into kid from app.keys where payment_id = p.id;
  if kid is not null then perform app.release_key(kid, 'Released by admin');
  elsif p.status in ('held', 'paid') then update app.payments set status = 'released', released_at = app.now() where id = p.id;
  end if;
  perform app.ping(p.student_id);
  return '{}'::jsonb;
end $$;

create or replace function public.refund_payment(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); p app.payments; h app.houses; k app.keys;
begin
  select * into p from app.payments where id = (a->>'id')::uuid for update;
  if p.id is null then perform app.fail('Payment not found.'); end if;
  if p.status = 'refunded' then perform app.fail('Already refunded.'); end if;
  select * into h from app.houses where id = p.house_id;
  perform app.refund_payment_row(p.id);
  if p.kind = 'inspection' then
    update app.inspections set status = 'cancelled', by_admin = true, refunded = true where payment_id = p.id and status = 'booked';
  else
    update app.keys set status = 'cancelled' where payment_id = p.id and status = 'active' returning * into k;
    if k.id is not null then
      update app.ballots set status = 'cancelled' where key_id = k.id and status = 'open';
    end if;
  end if;
  perform app.note(p.student_id, format('%s refunded for %s.', app.naira(p.amount), coalesce(h.title, 'your payment')));
  if h.id is not null then
    perform app.note(h.agent_id, format('Admin refunded %s''s payment for %s.', app.pname(p.student_id), h.title));
  end if;
  return '{}'::jsonb;
end $$;

-- Admin marks that the agent's share was sent to their bank (manual payouts).
create or replace function public.mark_paid_out(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); p app.payments; h app.houses;
begin
  update app.payments set paid_out_at = app.now() where id = (a->>'id')::uuid and status in ('released', 'paid') and paid_out_at is null
  returning * into p;
  if p.id is null then perform app.fail('Only released payments can be marked as paid out.'); end if;
  select * into h from app.houses where id = p.house_id;
  perform app.note(h.agent_id, format('%s for %s was sent to your payout account.', app.naira(app.net(p.amount)), h.title));
  return '{}'::jsonb;
end $$;

create or replace function public.set_complaint_status(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); cp app.complaints; st text := a->>'status';
begin
  if st not in ('open', 'review', 'resolved') then perform app.fail('Unknown status.'); end if;
  update app.complaints set status = st where id = (a->>'id')::uuid returning * into cp;
  if cp.author_id is not null then perform app.ping(cp.author_id); end if;
  if cp.agent_id is not null then perform app.ping(cp.agent_id); end if;
  -- a resolved dispute counts against the agent's trust score
  if st = 'resolved' and cp.kind = 'dispute' and cp.agent_id is not null and coalesce((a->>'upheld')::boolean, false) then
    update app.agents set disputes = disputes + 1 where id = cp.agent_id;
    perform app.update_trust(cp.agent_id);
  end if;
  return '{}'::jsonb;
end $$;

create or replace function public.toggle_complaint_removed(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); r boolean;
begin
  update app.complaints set removed = not removed where id = (a->>'id')::uuid returning removed into r;
  return jsonb_build_object('removed', r);
end $$;

create or replace function public.toggle_support_done(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); st text;
begin
  update app.support set status = case when status = 'answered' then 'new' else 'answered' end
   where id = (a->>'id')::uuid returning status into st;
  return jsonb_build_object('status', st);
end $$;

-- Draw a ballot now / pass a ballot offer to the next person (admin tools).
create or replace function public.run_draw(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare b app.ballots; n int := 0;
begin
  if not (app.cfg()).demo then perform app.need_admin(); end if;  -- demo panel lets anyone run draws
  for b in select * from app.ballots where status = 'open' and (nullif(a->>'id', '') is null or id = (a->>'id')::uuid) loop
    perform app.draw_ballot(b.id); n := n + 1;
  end loop;
  return jsonb_build_object('drawn', n);
end $$;

create or replace function public.pass_offer(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_admin(); b app.ballots;
begin
  select * into b from app.ballots where id = (a->>'id')::uuid and status = 'drawn';
  if b.id is null then perform app.fail('This ballot is not waiting on a payment.'); end if;
  perform app.advance_ballot(b.id);
  select * into b from app.ballots where id = b.id;
  return jsonb_build_object('status', b.status, 'to', case when b.status = 'drawn' then app.pname(b.draw_order[b.offer_idx + 1]) end);
end $$;

-- >>> db/core/60_social.sql
-- Chat, notifications, support, waitlist, profile and settings.

-- Messages that look like a request to pay outside the app.
create or replace function app.scam(txt text) returns boolean
language sql immutable as $$
  select txt ~* '(account\s*(no|number|details)|acct\s*no|send\s+(it|the\s+money|money)\s+to|pay\s+(?:\w+\s+)?(directly|outside|in\s+cash|cash)|transfer\s+(it\s+)?to\s+(my|me)|\y\d{10}\y)'
$$;

-- Open (or find) the chat between the signed-in student and a house's agent.
create or replace function public.open_thread(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_student(); h app.houses; tid uuid;
begin
  select * into h from app.houses where id = (a->>'houseId')::uuid and not deleted;
  if h.id is null then perform app.fail('House not found.'); end if;
  insert into app.threads(house_id, student_id, agent_id, created_at) values (h.id, u, h.agent_id, app.now())
  on conflict (house_id, student_id) do nothing;
  select id into tid from app.threads where house_id = h.id and student_id = u;
  update app.messages set read = true where thread_id = tid and sender = 'a' and not read;
  return jsonb_build_object('id', tid);
end $$;

create or replace function public.mark_thread_read(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); th app.threads;
begin
  select * into th from app.threads where id = (a->>'id')::uuid;
  if th.student_id = u then update app.messages set read = true where thread_id = th.id and sender = 'a' and not read;
  elsif th.agent_id = u then update app.messages set read = true where thread_id = th.id and sender = 's' and not read;
  end if;
  return '{}'::jsonb;
end $$;

create or replace function public.send_message(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); th app.threads; h app.houses; txt text := trim(coalesce(a->>'text', '')); s text; fl boolean;
begin
  if txt = '' then perform app.fail('Write a message first.'); end if;
  if length(txt) > 2000 then perform app.fail('Keep messages under 2,000 characters.'); end if;
  select * into th from app.threads where id = (a->>'id')::uuid;
  if th.id is null or (th.student_id <> u and th.agent_id <> u) then perform app.fail('Chat not found.'); end if;
  if th.student_id = u then perform app.need_student(); s := 's'; else perform app.need_agent(true); s := 'a'; end if;
  if th.blocked then perform app.fail('This chat is blocked.'); end if;
  fl := app.scam(txt);
  select * into h from app.houses where id = th.house_id;
  insert into app.messages(thread_id, sender, body, flag, created_at) values (th.id, s, txt, fl, clock_timestamp() + (app.now() - now()));
  if s = 's' then
    update app.messages set read = true where thread_id = th.id and sender = 'a' and not read;
    perform app.note(th.agent_id, format('New message from %s about %s.', app.pname(u), h.title));
  else
    update app.messages set read = true where thread_id = th.id and sender = 's' and not read;
    perform app.note(th.student_id, format('%s replied about %s.', app.pname(u), h.title));
  end if;
  if fl then perform app.note(null, format('Chat about %s flagged for a possible off-app payment request.', h.title)); end if;
  return jsonb_build_object('flag', fl);
end $$;

-- Demo only: the sample agent answers the sample student.
create or replace function public.demo_reply(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); th app.threads; h app.houses; lt text := lower(coalesce(a->>'text', '')); r text;
begin
  perform app.need_demo();
  select * into th from app.threads where id = (a->>'id')::uuid and student_id = u;
  if th.id is null or th.blocked then return '{}'::jsonb; end if;
  select * into h from app.houses where id = th.house_id;
  r := case
    when app.scam(a->>'text') then 'Please pay only through Lodgely. I can''t accept money outside the app.'
    when lt ~ '(water|light|power|nepa|meter|electric)' then 'Water is steady and light is on a prepaid meter. You can check both during the inspection.'
    when lt ~ '(price|reduce|discount|last price|negotiat)' then 'The price is fixed for this session. You pay it on Lodgely after the inspection, and Lodgely holds it until you move in.'
    when lt ~ '(inspect|visit|see it|come|when)' then 'Sure. Book any slot on the listing and I will meet you there with the door code.'
    else format('Thanks, %s. The room is still available. Book an inspection on the listing and I will meet you there.', app.first_name(u)) end;
  update app.messages set read = true where thread_id = th.id and sender = 's';
  insert into app.messages(thread_id, sender, body, created_at) values (th.id, 'a', r, clock_timestamp() + (app.now() - now()));
  perform app.note(u, format('%s replied about %s.', app.pname(th.agent_id), h.title));
  return '{}'::jsonb;
end $$;

create or replace function public.report_thread(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); th app.threads; h app.houses; by_ text; blk boolean := coalesce((a->>'block')::boolean, false);
begin
  select * into th from app.threads where id = (a->>'id')::uuid;
  if th.id is null or (th.student_id <> u and th.agent_id <> u) then perform app.fail('Chat not found.'); end if;
  by_ := case when th.agent_id = u then 'agent' else 'student' end;
  update app.threads set reported = true, report_reason = coalesce(nullif(a->>'reason', ''), 'Something else'),
    reported_by = by_, reported_at = app.now(), report_status = 'open',
    blocked = blocked or blk, blocked_by = case when blk then by_ else blocked_by end
   where id = th.id;
  select * into h from app.houses where id = th.house_id;
  perform app.note(null, format('A chat about %s was reported.', h.title));
  perform app.ping(case when by_ = 'agent' then th.student_id else th.agent_id end);
  return '{}'::jsonb;
end $$;

create or replace function public.mark_notes_read(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login();
begin
  update app.notifications set read = true where not read and (user_id = u or (user_id is null and app.role_of(u) = 'admin'));
  return '{}'::jsonb;
end $$;

-- Contact form (anyone, signed in or not).
create or replace function public.contact_support(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare nm text := trim(coalesce(a->>'name', '')); ct text := trim(coalesce(a->>'contact', '')); msg text := trim(coalesce(a->>'msg', ''));
  topic text := coalesce(nullif(a->>'topic', ''), 'Something else');
begin
  if nm = '' then perform app.fail('Add your name.'); end if;
  if not (ct ~ '^\S+@\S+\.\S+$' or ct ~ '^\+?\d[\d\s]{9,16}$') then perform app.fail('Add an email address or phone number so we can reply.'); end if;
  if length(msg) < 10 then perform app.fail('Tell us a little more in your message.'); end if;
  if length(msg) > 4000 then perform app.fail('Keep your message under 4,000 characters.'); end if;
  if (select count(*) from app.support where contact = ct and created_at > now() - interval '1 hour') >= 5 then
    perform app.fail('You have sent several messages in the last hour. We will reply soon.');
  end if;
  insert into app.support(user_id, name, contact, who, topic, msg, created_at)
  values (auth.uid(), nm, ct, coalesce(nullif(a->>'who', ''), 'Student'), topic, msg, app.now());
  perform app.note(null, format('New support message from %s: %s.', nm, topic));
  return '{}'::jsonb;
end $$;

create or replace function public.join_waitlist(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare ct text := trim(coalesce(a->>'contact', '')); sc text := coalesce(a->>'school', '');
begin
  if not (ct ~ '^\S+@\S+\.\S+$' or ct ~ '^\+?\d[\d\s]{9,16}$') then perform app.fail('Enter an email address or a phone number like 0803 123 4567.'); end if;
  if sc = '' then perform app.fail('Pick a school.'); end if;
  if not exists (select 1 from app.waitlist where school = sc and contact = ct) then
    insert into app.waitlist(school, contact, who, created_at) values (sc, ct, coalesce(nullif(a->>'who', ''), 'student'), app.now());
    perform app.note(null, format('New %s on the %s waitlist.', coalesce(nullif(a->>'who', ''), 'student'), upper(sc)));
  end if;
  return '{}'::jsonb;
end $$;

-- Profile. a = {email, dept, bio, photo} (only the fields sent are changed)
create or replace function public.save_profile(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); e text := trim(coalesce(a->>'email', ''));
begin
  if a ? 'email' and e <> '' and e !~ '^\S+@\S+\.\S+$' then perform app.fail('Enter a valid email address.'); end if;
  update app.profiles set
    email = case when a ? 'email' and e <> '' then e else email end,
    dept = case when a ? 'dept' and trim(a->>'dept') <> '' then trim(a->>'dept') else dept end,
    photo = case when a ? 'photo' then nullif(a->>'photo', '') else photo end,
    name = case when a ? 'name' and trim(a->>'name') <> '' then trim(a->>'name') else name end
   where id = u;
  if a ? 'bio' and app.role_of(u) = 'agent' then update app.agents set bio = trim(a->>'bio') where id = u; end if;
  return '{}'::jsonb;
end $$;

create or replace function public.save_prefs(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login();
begin
  update app.profiles set prefs = coalesce(a->'prefs', '{}'::jsonb) where id = u;
  return '{}'::jsonb;
end $$;

-- Phone number is confirmed by the app (demo code, or an SMS provider later).
create or replace function public.set_phone(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); ph text := trim(coalesce(a->>'phone', ''));
begin
  if ph !~ '^\+?\d[\d\s]{9,16}$' then perform app.fail('Enter a phone number like 0812 345 6789.'); end if;
  update app.profiles set phone = ph, phone_ok = false where id = u;
  perform app.note(u, format('Your phone number was changed to %s. If this wasn''t you, contact support.', ph));
  return '{}'::jsonb;
end $$;

create or replace function public.note_password_changed(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login();
begin
  perform app.note(u, 'Your password was changed. If this wasn''t you, contact support.');
  return '{}'::jsonb;
end $$;

-- What stops an account from being deleted right now.
create or replace function public.delete_account_check(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login();
begin
  return jsonb_build_object('busy', to_jsonb(array_remove(array[
    case when exists (select 1 from app.keys where student_id = u and status = 'active') then 'an active key' end,
    case when exists (select 1 from app.payments where student_id = u and status = 'held') then 'rent held by Lodgely' end,
    case when exists (select 1 from app.inspections where student_id = u and status = 'booked') then 'a booked visit' end,
    case when exists (select 1 from app.houses where agent_id = u and not deleted) then 'listings that are not deleted' end,
    case when app.savings_balance(u) > 0 then 'money in rent savings' end
  ], null)));
end $$;

-- Supabase replaces this to also remove the login (see db/supabase).
create or replace function app.delete_login(u uuid) returns void language sql as $$ select null::void $$;

-- Removes personal details; payment records stay (they are needed for accounting).
create or replace function public.delete_account(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
declare u uuid := app.need_login(); busy jsonb := public.delete_account_check('{}') -> 'busy';
begin
  if jsonb_array_length(busy) > 0 then perform app.fail('Finish these first: ' || (select string_agg(x, ', ') from jsonb_array_elements_text(busy) x) || '.'); end if;
  delete from app.favs where student_id = u;
  delete from app.savings_goals where student_id = u;
  delete from app.ballot_entries where student_id = u;
  update app.profiles set deleted = true, name = 'Deleted user', email = null, phone = null, photo = null, dept = null, prefs = '{}'::jsonb where id = u;
  perform app.delete_login(u);
  return '{}'::jsonb;
end $$;

-- >>> db/core/70_jobs.sql
-- Time-based rules. app.run_jobs() runs every minute (pg_cron on Supabase; the
-- app's ticker in demo mode). Every step is safe to repeat.

create or replace function app.draw_ballot(bid uuid) returns void
language plpgsql as $$
declare b app.ballots; h app.houses; r app.rooms; o uuid[]; i int;
begin
  select * into b from app.ballots where id = bid for update;
  if b.status <> 'open' then return; end if;
  select * into h from app.houses where id = b.house_id;
  select * into r from app.rooms where id = b.room_id;
  select coalesce(array_agg(e.student_id order by random()), '{}') into o
    from app.ballot_entries e join app.profiles p on p.id = e.student_id
   where e.ballot_id = b.id and not p.suspended and not p.deleted;
  if coalesce(array_length(o, 1), 0) = 0 then
    update app.ballots set status = 'lapsed' where id = b.id;
    perform app.note(h.agent_id, case when exists (select 1 from app.ballot_entries where ballot_id = b.id)
      then format('No eligible entries in the ballot for %s at %s. It lists normally when it frees up.', r.name, h.title)
      else format('Nobody entered the ballot for %s at %s. It lists normally when it frees up.', r.name, h.title) end);
    return;
  end if;
  update app.ballots set draw_order = o, status = 'drawn', offer_idx = 0, offer_at = app.now() where id = b.id;
  update app.rooms set hold_ballot = b.id where id = r.id;
  for i in 1 .. array_length(o, 1) loop
    perform app.note(o[i], case when i = 1
      then format('You won the ballot for %s at %s. Pay within %s hours to secure it.', r.name, h.title, (app.cfg()).offer_hours)
      else format('Ballot drawn for %s. You are number %s in line.', h.title, i) end);
  end loop;
  perform app.note(h.agent_id, format('Ballot drawn for %s at %s. %s has %s hours to pay.', r.name, h.title, app.pname(o[1]), (app.cfg()).offer_hours));
  perform app.note(null, format('Ballot drawn for %s with %s entries.', h.title, array_length(o, 1)));
end $$;

create or replace function app.advance_ballot(bid uuid) returns void
language plpgsql as $$
declare b app.ballots; h app.houses; r app.rooms; s uuid;
begin
  update app.ballots set offer_idx = offer_idx + 1 where id = bid returning * into b;
  select * into h from app.houses where id = b.house_id;
  select * into r from app.rooms where id = b.room_id;
  if b.offer_idx >= coalesce(array_length(b.draw_order, 1), 0) then
    update app.ballots set status = 'lapsed' where id = b.id;
    update app.rooms set hold_ballot = null where id = r.id and hold_ballot = b.id;
    perform app.note(h.agent_id, format('No ballot winner paid for %s at %s. It is open to everyone again.', r.name, h.title));
    return;
  end if;
  update app.ballots set offer_at = app.now() where id = b.id;
  s := b.draw_order[b.offer_idx + 1];
  perform app.note(s, format('The room at %s came to you from the ballot. Pay within %s hours to secure it.', h.title, (app.cfg()).offer_hours));
  perform app.note(h.agent_id, format('The ballot offer for %s passed to %s.', h.title, app.pname(s)));
end $$;

-- Demo only: a sample student who won a ballot pays after a few hours.
create or replace function app.demo_winner_pays(bid uuid) returns void
language plpgsql as $$
declare b app.ballots; h app.houses; r app.rooms; s uuid; pid uuid; k app.keys; st timestamptz; c app.settings := app.cfg();
begin
  select * into b from app.ballots where id = bid for update;
  select * into h from app.houses where id = b.house_id;
  select * into r from app.rooms where id = b.room_id;
  s := b.draw_order[b.offer_idx + 1];
  st := app.ballot_start(b);
  insert into app.payments(kind, student_id, house_id, room_id, amount, method, ref, status, created_at, paid_at, meta)
  values ('rent', s, h.id, r.id, r.price, 'Bank transfer', app.gen_ref(), 'held', app.now(), app.now(), jsonb_build_object('ballot_id', b.id))
  returning id into pid;
  insert into app.keys(code, payment_id, house_id, room_id, student_id, start_at, end_at, created_at)
  values (app.gen_key(), pid, h.id, r.id, s, st, st + make_interval(days => c.term_days), app.now()) returning * into k;
  update app.rooms set hold_ballot = null where id = r.id;
  update app.ballots set status = 'filled', winner_key = k.id where id = b.id;
  perform app.note(h.agent_id, format('%s won the ballot and paid %s for %s at %s. Lodgely holds it until move-in.', app.pname(s), app.naira(r.price), r.name, h.title));
  perform app.note(e.student_id, format('The ballot for %s has been filled.', h.title))
    from app.ballot_entries e where e.ballot_id = b.id and e.student_id <> s;
end $$;

create or replace function app.run_jobs() returns int
language plpgsql as $$
declare
  c app.settings := app.cfg(); t timestamptz := app.now(); n int := 0;
  k record; i record; b record; g record; p record;
  bal int; hit int[]; th int; nb app.ballots; v_due timestamptz; step interval; cnt int; left_ interval;
begin
  -- 1. Rent held too long without a move-in is released to the agent.
  for k in select k2.* from app.keys k2 join app.payments p2 on p2.id = k2.payment_id
            where k2.status = 'active' and not k2.moved_in and p2.status = 'held'
              and t - coalesce(p2.paid_at, p2.created_at) > make_interval(days => c.release_days) loop
    perform app.release_key(k.id, 'Auto-released after 7 days'); n := n + 1;
  end loop;

  -- 2. Keys that reached their end date: auto-renew from savings, or expire.
  for k in select k2.*, r.price, r.name as rname, r.cap, h.title, h.agent_id
             from app.keys k2 join app.rooms r on r.id = k2.room_id join app.houses h on h.id = k2.house_id
            where k2.status = 'active' and k2.end_at <= t for update of k2 loop
    if k.auto_renew and app.savings_balance(k.student_id) >= k.price
       and not exists (select 1 from app.ballots where key_id = k.id and status in ('drawn', 'filled')) then
      insert into app.payments(kind, student_id, house_id, room_id, amount, savings_used, method, ref, status, created_at, paid_at, released_at, meta)
      values ('renewal', k.student_id, k.house_id, k.room_id, k.price, k.price, 'Rent savings', app.gen_ref(), 'released', t, t, t, jsonb_build_object('key_id', k.id))
      returning * into p;
      insert into app.savings_txns(student_id, type, amt, note, payment_id, created_at)
      values (k.student_id, 'applied', k.price, 'Auto-renewal · ' || k.title, p.id, t);
      perform app.extend_key(k.id);
      perform app.note(k.student_id, format('Auto-renewed %s from savings. New end date %s.', k.title,
        app.fdate((select end_at from app.keys where id = k.id))));
      perform app.note(k.agent_id, format('%s renewed %s at %s for another %s days.', app.pname(k.student_id), k.rname, k.title, c.term_days));
      n := n + 1; continue;
    end if;
    update app.keys set status = 'expired' where id = k.id;
    select * into nb from app.ballots where key_id = k.id and status = 'open';
    if nb.id is not null then perform app.draw_ballot(nb.id); end if;
    cnt := app.active_count(k.room_id);
    perform app.note(k.agent_id, format('%s''s key for %s at %s ended.%s', app.pname(k.student_id), k.rname, k.title,
      case when cnt >= k.cap then ' The next tenant moves in now.'
           when exists (select 1 from app.rooms where id = k.room_id and hold_ballot is not null) then ' The room is held for the ballot winner.'
           else ' The room is listed as Available again.' end));
    perform app.note(k.student_id, format('Your key for %s has ended.%s', k.title,
      case when cnt >= k.cap then ' The next tenant moves in now.'
           when exists (select 1 from app.rooms where id = k.room_id and hold_ballot is not null) then ' The room is held for the ballot winner.'
           else ' The room is back on the market.' end));
    n := n + 1;
  end loop;

  -- 3. Ballots open when a room is within ballot_days of freeing up; 4. renewal reminders.
  for k in select k2.*, r.price, r.name as rname, h.title, h.agent_id
             from app.keys k2 join app.rooms r on r.id = k2.room_id join app.houses h on h.id = k2.house_id
            where k2.status = 'active' and k2.start_at <= t loop
    if k.end_at - t <= make_interval(days => c.ballot_days)
       and not exists (select 1 from app.ballots where key_id = k.id and status <> 'cancelled')
       and not exists (select 1 from app.keys x where x.room_id = k.room_id and x.status = 'active' and x.start_at > t)
       and not (k.auto_renew and app.savings_balance(k.student_id) >= k.price) then
      perform app.open_ballot(k.id, k.end_at);
      perform app.note(k.agent_id, format('%s at %s frees up on %s. Ballot entries are open, and %s keeps first right to renew.',
        k.rname, k.title, app.fdate(k.end_at), app.pname(k.student_id)));
      perform app.note(k.student_id, format('Other students can now enter a ballot for your room at %s. You keep first right to renew until %s.',
        k.title, app.fdate(k.end_at)));
      n := n + 1;
    end if;
    left_ := k.end_at - t;
    select coalesce(array_agg(x), '{}') into hit from unnest(array[60, 30, 7, 1]) x
     where left_ <= make_interval(days => x) and not (x = any (k.shown));
    if array_length(hit, 1) > 0 then
      update app.keys set shown = shown || hit where id = k.id;
      select min(x) into th from unnest(hit) x;
      perform app.note(k.student_id, format('%s day%s left on your key for %s. Renew in the app.', th, case when th > 1 then 's' else '' end, k.title));
      n := n + 1;
    end if;
  end loop;

  -- 5. Expired payment holds.
  update app.rooms set pay_hold_by = null, pay_hold_until = null where pay_hold_until is not null and pay_hold_until <= t;

  -- 6. Visit reminders 24 hours and 1 hour before.
  for i in select i2.*, h.title, h.address, h.agent_id from app.inspections i2 join app.houses h on h.id = i2.house_id
            where i2.status = 'booked' and i2.slot - t <= interval '24 hours' and i2.slot - t > interval '-1 hour'
              and not i2.r1 for update of i2 loop
    if i.slot - t <= interval '1 hour' then
      update app.inspections set r1 = true, r24 = true where id = i.id;
      perform app.note(i.student_id, format('Your visit to %s starts within the hour (%s). Meet %s at %s.', i.title, app.fslot(i.slot), app.pname(i.agent_id), i.address));
      perform app.note(i.agent_id, format('%s visits %s within the hour. Have your door code ready.', app.pname(i.student_id), i.title));
      n := n + 1;
    elsif not i.r24 then
      update app.inspections set r24 = true where id = i.id;
      perform app.note(i.student_id, format('Reminder: your visit to %s is on %s, less than 24 hours away.', i.title, app.fslot(i.slot)));
      perform app.note(i.agent_id, format('Reminder: %s visits %s on %s.', app.pname(i.student_id), i.title, app.fslot(i.slot)));
      n := n + 1;
    end if;
  end loop;

  -- 7. Scheduled savings. Simulated mode adds the deposits; with a real provider the student gets a reminder to top up.
  for g in select * from app.savings_goals where sched <> 'none' and sched_amt > 0 and next_auto is not null and next_auto <= t for update loop
    v_due := g.due::timestamp; step := make_interval(days => case when g.sched = 'weekly' then 7 else 30 end); cnt := 0;
    while g.next_auto <= t and g.next_auto <= v_due and cnt < 60 loop
      if c.payment_mode = 'simulated' then
        insert into app.savings_txns(student_id, type, amt, note, created_at)
        values (g.student_id, 'deposit', g.sched_amt, case when g.sched = 'weekly' then 'Weekly auto-save' else 'Monthly auto-save' end, g.next_auto);
      end if;
      g.next_auto := g.next_auto + step; cnt := cnt + 1;
    end loop;
    update app.savings_goals set next_auto = case when g.next_auto > v_due then null else g.next_auto end where student_id = g.student_id;
    if cnt > 0 then
      perform app.note(g.student_id, case when c.payment_mode = 'simulated'
        then format('%s of %s went into your rent savings.', case when cnt > 1 then cnt || ' automatic deposits' else 'An automatic deposit' end, app.naira(g.sched_amt))
        else format('Time for your %s savings top-up of %s. Add it from Savings.', g.sched, app.naira(g.sched_amt)) end);
      n := n + 1;
    end if;
  end loop;

  -- 8. Ballot draws and offers that ran out.
  for b in select * from app.ballots where status = 'open' and draw_at <= t loop
    perform app.draw_ballot(b.id); n := n + 1;
  end loop;
  for b in select * from app.ballots where status = 'drawn' loop
    if c.demo and b.draw_order[b.offer_idx + 1] = any (array(select app.sid('s' || x) from generate_series(2, 12) x))
       and t - b.offer_at > interval '6 hours' then
      perform app.demo_winner_pays(b.id); n := n + 1;
    elsif t - b.offer_at > make_interval(hours => c.offer_hours) then
      perform app.note(b.draw_order[b.offer_idx + 1], format('Your ballot offer for %s expired.', (select title from app.houses where id = b.house_id)));
      perform app.advance_ballot(b.id); n := n + 1;
    end if;
  end loop;

  -- 9. Checkouts nobody finished.
  update app.payments set status = 'expired' where status = 'pending' and created_at < t - interval '2 hours';
  return n;
end $$;

-- Demo mode: the app calls this every few seconds instead of a scheduler.
create or replace function public.demo_tick(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
begin
  perform app.need_demo();
  return jsonb_build_object('changed', app.run_jobs());
end $$;

-- Demo mode: move the clock (the time machine in the Demo panel).
create or replace function public.demo_set_clock(a jsonb) returns jsonb
language plpgsql security definer set search_path = app, public as $$
begin
  perform app.need_demo();
  update app.settings set shift_ms = greatest(0, coalesce((a->>'shift')::bigint, 0));
  return jsonb_build_object('changed', app.run_jobs(), 'shift', (app.cfg()).shift_ms);
end $$;

-- >>> db/supabase/00_supabase.sql
-- Supabase-only setup: logins, file storage, live refresh, the scheduler and permissions.

-- New login -> profile. The sign-up form passes role, name, phone, dept, school (and biz for agents).
-- Only 'student' and 'agent' can be chosen; admins are promoted by hand with app.make_admin().
create or replace function app.on_auth_user_created() returns trigger
language plpgsql security definer set search_path = app, public as $$
declare m jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
        r text := case when m->>'role' = 'agent' then 'agent' else 'student' end;
begin
  insert into app.profiles(id, role, name, email, phone, dept, school, created_at)
  values (new.id, r, coalesce(nullif(trim(m->>'name'), ''), split_part(new.email, '@', 1)), new.email,
          nullif(trim(m->>'phone'), ''), nullif(trim(m->>'dept'), ''), coalesce(nullif(m->>'school', ''), 'oau'), now())
  on conflict (id) do nothing;
  if r = 'agent' then
    insert into app.agents(id, biz, btype, rel) values (new.id, coalesce(trim(m->>'biz'), ''), m->>'btype', m->>'rel')
    on conflict (id) do nothing;
    perform app.note(null, format('New agent sign-up: %s. Documents to follow.', coalesce(m->>'name', new.email)));
  end if;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function app.on_auth_user_created();

create or replace function app.on_auth_user_email() returns trigger
language plpgsql security definer set search_path = app, public as $$
begin
  if new.email is distinct from old.email then update app.profiles set email = new.email where id = new.id; end if;
  return new;
end $$;

drop trigger if exists on_auth_user_email on auth.users;
create trigger on_auth_user_email after update of email on auth.users
  for each row execute function app.on_auth_user_email();

-- Deleting an account also removes the login (the anonymised profile and payments stay).
create or replace function app.delete_login(u uuid) returns void
language sql security definer as $$ delete from auth.users where id = u $$;

-- Run once in the SQL editor to make yourself an admin:  select app.make_admin('you@example.com');
create or replace function app.make_admin(p_email text) returns text
language plpgsql security definer set search_path = app, public as $$
declare u uuid;
begin
  select id into u from app.profiles where lower(email) = lower(p_email);
  if u is null then return 'No account with that email. Sign up in the app first.'; end if;
  delete from app.agents where id = u and not exists (select 1 from app.houses where agent_id = u);
  update app.profiles set role = 'admin' where id = u;
  return 'Done. Log out and back in.';
end $$;

-- Used by storage policies (they run as the signed-in user, who can't read app.*).
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = app, public as $$
  select exists (select 1 from app.profiles where id = auth.uid() and role = 'admin' and not deleted)
$$;

-- File storage.
--   media    public: listing photos, profile photos. Each person uploads into a folder named after their id.
--   private  agent verification documents. Readable by the owner and admins.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('media', 'media', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('private', 'private', false, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
on conflict (id) do nothing;

drop policy if exists "media upload own folder" on storage.objects;
create policy "media upload own folder" on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "media change own files" on storage.objects;
create policy "media change own files" on storage.objects for update to authenticated
  using (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "media delete own files" on storage.objects;
create policy "media delete own files" on storage.objects for delete to authenticated
  using (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "private upload own folder" on storage.objects;
create policy "private upload own folder" on storage.objects for insert to authenticated
  with check (bucket_id = 'private' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "private read own or admin" on storage.objects;
create policy "private read own or admin" on storage.objects for select to authenticated
  using (bucket_id = 'private' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin()));

-- Live refresh: the app subscribes to its own row in public.pings.
grant select on public.pings to authenticated;
do $$ begin
  alter publication supabase_realtime add table public.pings;
exception when duplicate_object then null; when undefined_object then raise notice 'Realtime publication not found; live refresh falls back to polling.';
end $$;

-- Permissions: the client only gets the API functions. Tables in "app" stay closed.
revoke all on schema app from public, anon, authenticated;
revoke execute on function public.payment_for_provider(text) from public, anon, authenticated;
revoke execute on function public.payment_confirmed(text, bigint, text, text) from public, anon, authenticated;
revoke execute on function public.set_payout_verified(uuid, text, text, text) from public, anon, authenticated;
grant execute on function public.payment_for_provider(text) to service_role;
grant execute on function public.payment_confirmed(text, bigint, text, text) to service_role;
grant execute on function public.set_payout_verified(uuid, text, text, text) to service_role;

-- Scheduler: run the time-based rules every minute (needs the pg_cron extension, on by default in new projects).
do $$ begin
  create extension if not exists pg_cron;
  perform cron.unschedule(jobid) from cron.job where jobname = 'app-jobs';
  perform cron.schedule('app-jobs', '* * * * *', 'select app.run_jobs()');
exception when others then
  raise notice 'pg_cron is not available (%). Turn it on under Database > Extensions, then run: select cron.schedule(''app-jobs'', ''* * * * *'', ''select app.run_jobs()'');', sqlerrm;
end $$;
